INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-001', 'Para un equipo caliente con ventilador ruidoso o alarma de temperatura', 'Para un equipo caliente con ventilador ruidoso o alarma de temperatura, limpiar disipadores, verificar pasta termica y revisar flujo de ventilacion.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-002', 'En caidas de red', 'En caidas de red, internet o fallas de resolucion DNS, verificar cable ethernet, renovar IP con ipconfig /renew y probar ping al gateway o servidor DNS.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-003', 'Para cuentas bloqueadas o problemas de inicio de sesion', 'Para cuentas bloqueadas o problemas de inicio de sesion, verificar intentos fallidos en Active Directory, desbloquear usuario y restablecer credenciales temporales.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-004', 'Si el token o codigo MFA no llega al dispositivo movil', 'Si el token o codigo MFA no llega al dispositivo movil, validar sincronizacion horaria de Microsoft Authenticator o generar codigo de paso temporal de contingencia.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-005', 'Cuando una aplicacion como Excel o el ERP se cierra con error inesperado o memor', 'Cuando una aplicacion como Excel o el ERP se cierra con error inesperado o memoria violada, revisar complementos conflictivos, actualizar version y consultar visor de eventos.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-006', 'Para impresoras con atascos frecuentes de papel o impresion manchada', 'Para impresoras con atascos frecuentes de papel o impresion manchada, retirar residuos del rodillo de alimentacion, revisar nivel de toner y reiniciar cola de impresion.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-007', 'Si el monitor parpadea', 'Si el monitor parpadea, no enciende o emite pantalla negra, verificar cables HDMI o DisplayPort, actualizar controlador de video y probar conexion directa sin dock.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-008', 'Ante lentitud extrema del sistema operativo o congelamiento', 'Ante lentitud extrema del sistema operativo o congelamiento, inspeccionar consumo de CPU, memoria y disco en el administrador de tareas y deshabilitar servicios innecesarios.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-009', 'Si el cliente VPN falla al negociar el tunel o se desconecta intermitentemente', 'Si el cliente VPN falla al negociar el tunel o se desconecta intermitentemente, validar certificado digital de seguridad, probar protocolo alternativo y verificar enlace del proveedor.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-010', 'Para errores de acceso denegado en recursos compartidos de red', 'Para errores de acceso denegado en recursos compartidos de red, verificar membresia en grupos de seguridad NTFS y corroborar la ruta de red SMB asignada.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-011', 'Si la bateria de la laptop no carga o se descarga rapidamente', 'Si la bateria de la laptop no carga o se descarga rapidamente, calibrar ciclos de carga en BIOS, verificar cargador con multimetro y actualizar controlador ACPI.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-012', 'Ante teclado o touchpad que no responde o tras derrame accidental de liquidos', 'Ante teclado o touchpad que no responde o tras derrame accidental de liquidos, desconectar bateria de inmediato, secar componentes y probar con periferico USB externo.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-013', 'Si la pantalla azul BSOD muestra error de memoria o volcado de memoria fisica', 'Si la pantalla azul BSOD muestra error de memoria o volcado de memoria fisica, ejecutar diagnostico de memoria de Windows mdsched y comprobar modulos RAM con MemTest86.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-014', 'Para fallas en discos duros con ruidos mecanicos o sectores defectuosos', 'Para fallas en discos duros con ruidos mecanicos o sectores defectuosos, ejecutar analisis SMART con CrystalDiskInfo, realizar chkdsk /f /r y programar respaldo prioritario.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-015', 'Si la estacion de acoplamiento dock USB-C o Thunderbolt no reconoce perifericos', 'Si la estacion de acoplamiento dock USB-C o Thunderbolt no reconoce perifericos, actualizar firmware del dock, reinstalar drivers Thunderbolt y verificar suministro de energia.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-016', 'Ante escaner o camara web no detectada en videollamadas', 'Ante escaner o camara web no detectada en videollamadas, verificar permisos de privacidad en Windows, reinstalar driver de imagen y probar en puerto USB directo.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-017', 'Si el equipo emite pitidos al encender y no da video en el arranque POST', 'Si el equipo emite pitidos al encender y no da video en el arranque POST, verificar codigos de beep del fabricante, limpiar contactos dorados de RAM y tarjeta grafica.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-018', 'Para fuentes de poder o cargadores con olor a quemado', 'Para fuentes de poder o cargadores con olor a quemado, zumbido electrico o chispas, retirar de la corriente electrica de inmediato y sustituir unidad de potencia.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-019', 'Si la bisagra del portatil esta rota o la carcasa abierta', 'Si la bisagra del portatil esta rota o la carcasa abierta, desarmar con precaucion para evitar tension sobre el cable flex de pantalla y solicitar repuesto mecanico.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-020', 'Ante fallas en audifonos o microfono con distorsion de audio en llamadas', 'Ante fallas en audifonos o microfono con distorsion de audio en llamadas, reiniciar servicio de audio de Windows, configurar dispositivo predeterminado y actualizar Realtek.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-021', 'En caidas de conexion WiFi por senal debil o cortes intermitentes', 'En caidas de conexion WiFi por senal debil o cortes intermitentes, cambiar canal de transmision en el router, deshabilitar ahorro de energia del adaptador y olvidar red.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-022', 'Si no es posible obtener direccion IP por fallo de DHCP', 'Si no es posible obtener direccion IP por fallo de DHCP, reiniciar servicio cliente DHCP, comprobar rango de concesiones en el servidor y asignar IP estatica provisional.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-023', 'Para perdidas de paquetes y alta latencia o jitter en llamadas de Teams o Zoom', 'Para perdidas de paquetes y alta latencia o jitter en llamadas de Teams o Zoom, verificar saturacion de ancho de banda, probar cable de red directo y priorizar trafico con QoS.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-024', 'Si el enlace troncal de fibra optica o conexion WAN principal se cae', 'Si el enlace troncal de fibra optica o conexion WAN principal se cae, verificar luces de estado en el modem ONT, conmutar a enlace de contingencia 4G y reportar al ISP.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-025', 'Ante conflictos de direccion IP duplicada en la red local', 'Ante conflictos de direccion IP duplicada en la red local, rastrear MAC address conflictiva con arp -a, liberar direccion en DHCP y reiniciar tarjeta de red.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-026', 'Si el firewall corporativo bloquea puertos requeridos como 443 80 o 3389', 'Si el firewall corporativo bloquea puertos requeridos como 443 80 o 3389, validar reglas de trafico saliente en Windows Defender Firewall y consultar politicas de perimetro.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-027', 'Para errores de proxy que impiden navegar en navegadores web', 'Para errores de proxy que impiden navegar en navegadores web, verificar configuracion automatica PAC, desmarcar servidor proxy manual y reiniciar winsock con netsh.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-028', 'Si la conexion remota por Escritorio Remoto RDP no responde', 'Si la conexion remota por Escritorio Remoto RDP no responde, validar que el servicio TermService este activo, revisar puerto 3389 y verificar acceso en lista de usuarios remotos.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-029', 'En fallas de resolucion de nombres NetBIOS o recursos compartidos por nombre de ', 'En fallas de resolucion de nombres NetBIOS o recursos compartidos por nombre de host, vaciar cache DNS con ipconfig /flushdns y corroborar archivo hosts de Windows.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-030', 'Si la sesion VPN muestra error de certificado revocado o vencido', 'Si la sesion VPN muestra error de certificado revocado o vencido, regenerar certificado de usuario en la entidad CA corporativa y reinstalar perfil de conexion.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-031', 'Para contrasenas corporativas caducadas en Active Directory o Entra ID', 'Para contrasenas corporativas caducadas en Active Directory o Entra ID, validar identidad del usuario por canal seguro, restablecer credencial y forzar cambio en proximo inicio.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-032', 'Si el usuario requiere permisos de lectura o modificacion en carpeta compartida', 'Si el usuario requiere permisos de lectura o modificacion en carpeta compartida, solicitar aprobacion del dueno de datos y agregarlo al grupo de seguridad AD correspondiente.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-033', 'Ante bloqueo de BitLocker solicitando clave de recuperacion de 48 digitos', 'Ante bloqueo de BitLocker solicitando clave de recuperacion de 48 digitos, consultar consola de Microsoft Entra o Active Directory, validar GUID y aplicar desbloqueo.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-034', 'Si el token de hardware o aplicacion de seguridad de doble factor se desincroniz', 'Si el token de hardware o aplicacion de seguridad de doble factor se desincronizo tras cambio de celular, revocar metodo anterior y guiar nuevo enrolamiento mediante codigo QR.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-035', 'Para errores de autenticacion Single Sign-On SSO en portales corporativos', 'Para errores de autenticacion Single Sign-On SSO en portales corporativos, limpiar cookies de sesion del navegador, sincronizar hora del equipo con NTP y probar modo incognito.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-036', 'Si el usuario recibe error de acceso prohibido HTTP 403 en aplicaciones web inte', 'Si el usuario recibe error de acceso prohibido HTTP 403 en aplicaciones web internas, verificar roles de usuario asignados en la base de datos y corroborar claims del token JWT.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-037', 'Para solicitudes de privilegios de administrador local temporal para instalar so', 'Para solicitudes de privilegios de administrador local temporal para instalar software autorizado, generar aprobacion en mesa de ayuda y elevar credenciales con LAPS.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-038', 'Si una cuenta de servicio de aplicacion queda deshabilitada o bloqueada', 'Si una cuenta de servicio de aplicacion queda deshabilitada o bloqueada, verificar tareas programadas con credenciales antiguas y actualizar clave en servicios de Windows.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-039', 'Ante sospecha de cuenta comprometida o actividad inusual de inicio de sesion', 'Ante sospecha de cuenta comprometida o actividad inusual de inicio de sesion, revocar todas las sesiones activas en Azure AD, bloquear inicio de sesion y auditar logs de acceso.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-040', 'Para llaves de seguridad FIDO2 o tarjetas inteligentes no leidas por el lector', 'Para llaves de seguridad FIDO2 o tarjetas inteligentes no leidas por el lector, reiniciar servicio de tarjeta inteligente SCardSvr y reinstalar controlador del lector.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-041', 'Cuando Microsoft Outlook se congela o no abre la bandeja de entrada', 'Cuando Microsoft Outlook se congela o no abre la bandeja de entrada, iniciar en modo seguro outlook /safe, deshabilitar complementos conflictivos y reparar archivo OST o PST.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-042', 'Si Microsoft Excel se bloquea al ejecutar macros VBA o tablas dinamicas pesadas', 'Si Microsoft Excel se bloquea al ejecutar macros VBA o tablas dinamicas pesadas, verificar calculo manual, auditar bucles infinitos en el codigo VBA y limpiar hojas ocultas.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-043', 'Para sincronizacion fallida de OneDrive con archivos bloqueados en bucle', 'Para sincronizacion fallida de OneDrive con archivos bloqueados en bucle, pausar y reanudar sincronizacion, reiniciar proceso onedrive.exe /reset y verificar espacio en cuota.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-044', 'Si una aplicacion corporativa o ERP no conecta con la base de datos SQL', 'Si una aplicacion corporativa o ERP no conecta con la base de datos SQL, verificar cadena de conexion, comprobar ping al servidor de base de datos y validar puerto 1433.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-045', 'Ante errores de activacion de licencia en Microsoft 365 o Windows', 'Ante errores de activacion de licencia en Microsoft 365 o Windows, ejecutar script ospp.vbs para limpiar llaves previas, validar conectividad con servidor KMS y reautenticar.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-046', 'Si el programa Word u Office no abre', 'Si el programa Word u Office no abre, no deja ingresar o se congela mientras Excel o PowerPoint si abren, iniciar en modo seguro con winword /safe, eliminar plantilla Normal.dotm corrupta, deshabilitar complementos COM o ejecutar reparacion rapida de Office.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-047', 'Para presentaciones de PowerPoint que se bloquean', 'Para presentaciones de PowerPoint que se bloquean, se congelan o no reproducen videos incrustados, deshabilitar aceleracion grafica por hardware en opciones avanzadas y comprimir elementos multimedia.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-048', 'Si Microsoft Teams presenta pantalla negra en videollamadas o no reconoce camara', 'Si Microsoft Teams presenta pantalla negra en videollamadas o no reconoce camara ni microfono, borrar cache en AppData Microsoft Teams, reiniciar proceso y verificar permisos de dispositivo.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-049', 'Cuando archivos PDF no abren o Adobe Acrobat Reader se cuelga al imprimir o firm', 'Cuando archivos PDF no abren o Adobe Acrobat Reader se cuelga al imprimir o firmar, desactivar modo protegido al iniciar en preferencias de seguridad y reparar instalacion de Acrobat.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-050', 'Si el navegador Google Chrome o Microsoft Edge se cierra solo', 'Si el navegador Google Chrome o Microsoft Edge se cierra solo, muestra error Oh no o no carga paginas web, borrar cookies y cache, desactivar extensiones y restablecer configuracion predeterminada.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-051', 'Para un computador o torre que no prende', 'Para un computador o torre que no prende, no sube ni arranca al presionar el boton, revisar switch de encendido del panel frontal, puentear pines de la tarjeta madre y probar fuente de poder con clip.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-052', 'Si el computador o portatil se apago repentinamente por sobrecalentamiento o se ', 'Si el computador o portatil se apago repentinamente por sobrecalentamiento o se tosto por exceso de calor, destapar disipador, limpiar motas de polvo en ventilador y aplicar pasta termica fresca.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-053', 'Ante pantalla negra tras encender la maquina sin mostrar imagen ni logotipo', 'Ante pantalla negra tras encender la maquina sin mostrar imagen ni logotipo, realizar drenado de energia estatica o hard reset manteniendo pulsado el boton de encendido treinta segundos sin corriente.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-054', 'Si los puertos USB no leen memorias', 'Si los puertos USB no leen memorias, mouse ni perifericos, deshabilitar suspension selectiva de USB en opciones del plan de energia de Windows y reinstalar controladores del concentrador raiz USB.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-055', 'Para laptops o equipos con bateria inflada o abombada que deforma la carcasa', 'Para laptops o equipos con bateria inflada o abombada que deforma la carcasa, desconectar inmediatamente el cargador por riesgo de fuga de litio, apagar el equipo y reemplazar bateria.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-056', 'En impresoras termicas de etiquetas Zebra o POS que imprimen en blanco o desalin', 'En impresoras termicas de etiquetas Zebra o POS que imprimen en blanco o desalineado, calibrar sensor de gap o marca negra, limpiar cabezal termico con alcohol isopropilico y verificar puerto USB.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-057', 'Si el lector de codigo de barras USB no transmite lecturas o no presiona enter a', 'Si el lector de codigo de barras USB no transmite lecturas o no presiona enter automaticamente, escanear codigos de programacion de fabrica del manual y configurar sufijo Carriage Return.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-058', 'Ante lector biometrico de huella digital que no reconoce accesos o muestra senso', 'Ante lector biometrico de huella digital que no reconoce accesos o muestra sensor no disponible, reiniciar servicio de biometria de Windows WbioSrvc y reinstalar driver del lector dactilar.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-059', 'Si la conexion WiFi se cae a cada rato', 'Si la conexion WiFi se cae a cada rato, presenta desconexiones intermitentes o dice sin internet segura, ejecutar netsh winsock reset, reiniciar pila TCP IP y desmarcar ahorro de energia del adaptador.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-060', 'Para errores de conexion VPN 800 u 809 al trabajar remoto desde casa', 'Para errores de conexion VPN 800 u 809 al trabajar remoto desde casa, configurar valor AssumeUDPEncapsulationContextOnSendRule en el registro de Windows y abrir puertos IPsec en el router casero.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-061', 'Ante lentitud extrema y caida de velocidad en teletrabajo durante llamadas y esc', 'Ante lentitud extrema y caida de velocidad en teletrabajo durante llamadas y escritorio remoto, realizar prueba de ping y latencia hacia el servidor, conectar cable UTP directo y cambiar DNS a publicos.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-062', 'Si el acceso a carpetas compartidas de red muestra credenciales invalidas o erro', 'Si el acceso a carpetas compartidas de red muestra credenciales invalidas o error de protocolo SMB, habilitar cliente SMB2 o SMB3 y eliminar claves obsoletas en el Administrador de Credenciales cmdkey.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-063', 'Cuando herramientas de soporte remoto como AnyDesk o TeamViewer no conectan o re', 'Cuando herramientas de soporte remoto como AnyDesk o TeamViewer no conectan o rechazan sesion remota, autorizar puertos en el firewall corporativo, comprobar ID de cliente y solicitar elevacion UAC.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-064', 'Si Windows Update entra en bucle infinito de instalacion o muestra deshaciendo c', 'Si Windows Update entra en bucle infinito de instalacion o muestra deshaciendo cambios, detener servicios wuauserv y bits, vaciar carpeta SoftwareDistribution y ejecutar comando sfc /scannow.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-065', 'Para uso de disco duro al 100 por ciento continuo que ralentiza la maquina', 'Para uso de disco duro al 100 por ciento continuo que ralentiza la maquina, deshabilitar servicio SysMain SuperFetch en servicios de Windows, ejecutar liberador de espacio cleanmgr y comprobar disco.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-066', 'Ante infeccion por virus', 'Ante infeccion por virus, ventanas emergentes pop-ups o sospecha de ransomware, aislar el computador de la red corporativa, ejecutar examen con Windows Defender Offline y purgar tareas programadas.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-067', 'Para problemas al firmar documentos tributarios o ingresar a portales de la DIAN', 'Para problemas al firmar documentos tributarios o ingresar a portales de la DIAN con certificado digital, importar archivo p12 o pfx en el almacen personal de certificados y validar vigencia.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-068', 'Si el token fisico o tarjeta criptografica SafeNet o ePass no es detectada para ', 'Si el token fisico o tarjeta criptografica SafeNet o ePass no es detectada para firma electronica, reiniciar servicio de tarjeta inteligente SCardSvr e instalar el middleware criptografico del proveedor.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-069', 'Cuando el software contable o ERP como Siigo', 'Cuando el software contable o ERP como Siigo, World Office, Helisa o Novasoft se bloquea o pierde conexion con el servidor, validar conectividad al puerto de SQL Server y permisos en la carpeta compartida.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-070', 'Si el aplicativo SAP GUI se cierra con error de conexion o timeout de red', 'Si el aplicativo SAP GUI se cierra con error de conexion o timeout de red, verificar servidor de mensajes en archivo saplogon.ini, comprobar puerto TCP 3200 y probar enlace VPN con la sede central.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-071', 'Para fallos de envio en facturacion electronica hacia la DIAN con error de timeo', 'Para fallos de envio en facturacion electronica hacia la DIAN con error de timeout o token vencido, verificar vigencia del certificado digital de facturacion y sincronizacion con el webservice DIAN.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-072', 'Si portales web bancarios o estatales no cargan por bloqueo de Java o Applets an', 'Si portales web bancarios o estatales no cargan por bloqueo de Java o Applets antiguos, anadir la URL a la lista de excepciones en el panel de control de Java y habilitar TLS 1.2.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-073', 'Cuando la pantalla se congela repentinamente', 'Cuando la pantalla se congela repentinamente, se pega o se cuelga la imagen pero el audio sigue activo, reiniciar controlador de pantalla con el atajo Windows mas Ctrl mas Shift mas B.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-074', 'Para proyectores o monitores externos en salas de reuniones que no proyectan ima', 'Para proyectores o monitores externos en salas de reuniones que no proyectan imagen, presionar Windows mas P para cambiar a modo extender y verificar resolucion de video compatible con el cable HDMI.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido) VALUES ('SOP-KB-075', 'Si la bandeja de entrada de correo corporativo muestra buzon lleno y no permite ', 'Si la bandeja de entrada de correo corporativo muestra buzon lleno y no permite enviar correos, archivar elementos antiguos a un archivo PST local o solicitar ampliacion de cuota a administracion.') ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-076', 'Diagnóstico y mitigación de alarma de temperatura y sobrecalentamiento en servidores de rack', 'Paso 1: Acceder a la consola de gestión fuera de banda (iLO/iDRAC) y verificar sensores térmicos de CPU y memoria. Paso 2: Comprobar el estado de los ventiladores redundantes y retirar obstrucciones en el flujo de aire frontal o posterior del rack. Paso 3: Verificar que el aire acondicionado de la sala de cómputo mantenga una temperatura entre 18°C y 22°C. Paso 4: Si un ventilador falló, activar ventilación de contingencia y reemplazar el módulo hot-plug. Paso 5: Confirmar normalización de temperatura bajo 65°C y limpiar alertas en el registro SEL.', 'No abrir el chasis con el servidor en producción si se vulnera la contención de flujo de aire térmico. Utilizar pulsera antiestática ESD.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-077', 'Reconstrucción y reemplazo en caliente (hot-swap) de discos en arreglos RAID degradados', 'Paso 1: Identificar el disco fallido mediante el LED ámbar parpadeante y validar el slot exacto en el software de gestión RAID (MegaRAID / Smart Storage). Paso 2: Verificar la existencia de un respaldo reciente antes de cualquier intervención. Paso 3: Retirar la bahía hot-swap defectuosa y colocar la unidad de repuesto con idénticas o superiores especificaciones certificadas. Paso 4: Monitorear el inicio automático de la reconstrucción (rebuild) y priorizar la tasa de I/O al 30% para no penalizar producción. Paso 5: Validar estado Optimal del arreglo y registrar serial en inventario.', 'Nunca retirar más de un disco simultáneamente en arreglos RAID 5 o RAID 1. Confirmar siempre el número de slot físico.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-078', 'Falla de fuente de poder redundante en servidores y switches modulares de centro de datos', 'Paso 1: Inspeccionar el LED de estado de las fuentes de poder (PSU 1 y PSU 2) y verificar alerta en consola iDRAC/iLO o syslog. Paso 2: Comprobar si la pérdida de energía proviene de la PDU A o PDU B mediante multímetro o medidor de PDU. Paso 3: Si la alimentación eléctrica externa es correcta, retirar la fuente fallida presionando la palanca de liberación rápida. Paso 4: Insertar la fuente de repuesto con el mismo wattage y conectar el cable de retención C13/C14. Paso 5: Validar que el LED cambie a verde continuo y desaparezca la alarma de pérdida de redundancia.', 'Verificar que la segunda fuente esté activa y soportando la carga total antes de desacoplar la fuente averiada.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-079', 'Diagnóstico de estaciones de trabajo que no encienden por fallo de switch frontal o placa madre', 'Paso 1: Desconectar el cable de alimentación y verificar voltaje en la toma eléctrica con probador de fase. Paso 2: Inspeccionar el botón de encendido del chasis y revisar la conexión de los pines PWR_SW en el panel frontal de la placa madre. Paso 3: Realizar puenteo momentáneo con destornillador aislado en los pines PWR_SW para descartar botón mecánico dañado. Paso 4: Si no reacciona, probar la fuente de poder con clip puenteando cable verde (PS_ON) y cable negro (COM) o probador digital ATX. Paso 5: Si la fuente enciende pero la placa no responde, diagnosticar cortocircuito en condensadores de la placa madre.', 'Desconectar siempre la energía eléctrica antes de intervenir conectores internos de la placa base.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-080', 'Falla de docking station Thunderbolt / USB-C que desconecta aleatoriamente monitores o red', 'Paso 1: Desconectar todos los periféricos y el cable host Thunderbolt/USB-C. Paso 2: Realizar reinicio de energía (power cycle) del dock desconectando su transformador de corriente durante 60 segundos. Paso 3: En el equipo portátil, actualizar el firmware del controlador Thunderbolt y los controladores de chipset Intel/AMD. Paso 4: Actualizar el firmware interno del dock mediante la utilidad oficial del fabricante (Dell Command Update / Lenovo Dock Manager). Paso 5: Reconectar primero el video y luego la red Ethernet gigabit para confirmar estabilidad de enlace.', 'Utilizar cables Thunderbolt certificados de 40 Gbps de longitud no mayor a 0.8 metros para prevenir pérdida de señal en altas resoluciones.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-081', 'Procedimiento ante abombamiento o hinchazón de baterías de iones de litio en portátiles', 'Paso 1: Apagar inmediatamente el computador portátil y desconectar el cargador para evitar sobrecarga o perforación de celdas. Paso 2: Aislar el equipo en una superficie no inflamable y alejada de fuentes de calor. Paso 3: Con guantes de nitrilo y gafas de protección, desatornillar la cubierta inferior con destornillador Torx/Philips sin ejercer presión sobre la batería. Paso 4: Desconectar el flex de la batería a la placa madre y depositar la batería inflada en un contenedor ignífugo para residuos peligrosos. Paso 5: Reemplazar con batería original del fabricante y calibrar ciclo de carga.', 'PELIGRO DE INCENDIO QUÍMICO. Jamás perforar, doblar ni golpear una celda de batería inflada.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-082', 'Corrección de parpadeo de video y pérdida de sincronía en monitores DisplayPort y HDMI', 'Paso 1: Presionar atajo Windows + Ctrl + Shift + B para reiniciar el subsistema de controladores gráficos de Windows. Paso 2: Verificar que el cable DisplayPort cuente con certificación VESA 1.4 y no tenga el pin 20 energizado. Paso 3: En Configuración de Pantalla Avanzada, reducir la tasa de refresco a 60 Hz y verificar resolución nativa del panel. Paso 4: Reinstalar el controlador gráfico utilizando instalación limpia (DDU / clean install en driver NVIDIA, AMD o Intel Graphics). Paso 5: Probar conexión directa sin adaptadores pasivos VGA/DVI intermedios.', 'No forzar resoluciones o frecuencias de actualización fuera de la especificación técnica del fabricante del monitor.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-083', 'Detección y sustitución de sectores defectuosos en discos mecánicos y SSD con fallas SMART', 'Paso 1: Ejecutar CrystalDiskInfo o wmic diskdrive get status para leer atributos SMART 05 (Reallocated Sectors) y 0BB (Reported Uncorrectable). Paso 2: Si el estado SMART indica Riesgo o Precaución, suspender escrituras de inmediato y ejecutar imagen bit a bit hacia unidad de respaldo. Paso 3: Sustituir la unidad física dañada por un disco SSD NVMe PCIe de capacidad equivalente o superior. Paso 4: Restaurar la partición del sistema y datos desde la imagen limpia. Paso 5: Ejecutar chkdsk /f sobre la nueva unidad para corroborar integridad del sistema de archivos NTFS.', 'No ejecutar chkdsk /r sobre discos mecánicos con ruidos de clic o cabezal rozando, ya que destruirá permanentemente los sectores dañados.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-084', 'Diagnóstico y limpieza de teclado tras derrame de líquidos y prueba de cortocircuito', 'Paso 1: Desconectar inmediatamente el teclado del puerto USB o retirar la batería del portátil si el derrame fue sobre laptop. Paso 2: Colocar el equipo o teclado boca abajo sobre paño absorbente para impedir el avance del líquido hacia la placa lógica. Paso 3: Limpiar los residuos con alcohol isopropílico al 99% en spray y brocha antiestática para disolver azúcares y sales minerales. Paso 4: Dejar secar en cámara de aire templado por un mínimo de 12 horas. Paso 5: Probar continuidad con multímetro y ejecutar Keyboard Test Utility para verificar que ninguna tecla quede pulsada.', 'No utilizar pistolas de calor ni secadores de pelo a alta temperatura que puedan deformar las membranas de goma o teclas de plástico ABS.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-085', 'Procedimiento de drenaje estático profundo (hard reset) para equipos que no superan el POST', 'Paso 1: Desconectar el cable de corriente eléctrica y desacoplar la batería externa si es portátil. Paso 2: Desconectar todos los periféricos USB, cables de red, monitores secundarios y tarjetas SD. Paso 3: Mantener presionado el botón de encendido de forma continua durante 45 segundos para descargar condensadores de la placa madre. Paso 4: Reconectar exclusivamente el adaptador de corriente directo a la toma de pared. Paso 5: Encender el equipo y esperar dos ciclos de reinicio automático mientras la BIOS reentrena la memoria RAM.', 'Asegurarse de que el equipo esté completamente desconectado de la energía antes de iniciar el drenaje estático.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-086', 'Diagnóstico de memorias RAM ECC en servidores con fallos single-bit y multi-bit recurrentes', 'Paso 1: Revisar los registros IPMI System Event Log (SEL) para identificar el socket de procesador y el canal DIMM afectado (ej. CPU1_DIMM_A1). Paso 2: Si los errores son single-bit corregibles pero superan el umbral de advertencia, programar ventana de mantenimiento. Paso 3: En mantenimiento, apagar el servidor, retirar el módulo DIMM sospechoso y limpiar contactos con borrador electrostático y alcohol isopropílico. Paso 4: Intercambiar de canal con un módulo adyacente para aislar si la falla sigue al módulo o permanece en el slot de la placa madre. Paso 5: Si el error persiste en el módulo, sustituir con memoria certificada del fabricante.', 'Manejar los módulos DIMM sujetándolos únicamente por los bordes laterales sin tocar los circuitos integrados ni contactos dorados.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-087', 'Reemplazo de rodillos de arrastre (pickup rollers) en impresoras láser con atascos frecuentes', 'Paso 1: Apagar la impresora láser y esperar 20 minutos hasta que la unidad fusora reduzca su temperatura. Paso 2: Retirar la bandeja de papel número 2 y localizar el rodillo de goma de alimentación (pickup roller). Paso 3: Presionar las pestañas plásticas laterales para desacoplar el rodillo desgastado y liso. Paso 4: Limpiar el eje metálico e instalar el nuevo rodillo original cerciorándose de que la superficie de goma tenga estrías de tracción. Paso 5: Cargar papel nuevo sin humedad, ajustar las guías de ancho de bandeja y ejecutar prueba de 20 páginas continuas.', 'La unidad fusora alcanza temperaturas superiores a 200°C. Evitar tocar partes metálicas cercanas al rodillo de presión caliente.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-088', 'Calibración de sensor y ajuste de cabezal térmico en impresoras Zebra y terminales POS', 'Paso 1: Apagar la impresora térmica e inspeccionar el cabezal de impresión con un hisopo impregnado de alcohol isopropílico. Paso 2: Ajustar el sensor de marca negra (black mark) o sensor de espacio (gap sensor) alineándolo con el troquel de las etiquetas. Paso 3: Encender la impresora manteniendo presionado el botón Feed/Pause para iniciar la calibración automática de sensor (sensor profile). Paso 4: En el controlador ZebraDesigner o driver POS, configurar la velocidad a 4 ips y ajustar la oscuridad (darkness) al nivel óptimo. Paso 5: Emitir una etiqueta de prueba y verificar alineación milimétrica y nitidez del código de barras.', 'No utilizar objetos punzantes metálicos para retirar residuos adheridos al cabezal térmico; rayará la superficie de calentamiento.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-089', 'Configuración de lectores de código de barras USB/Bluetooth con sufijo Carriage Return', 'Paso 1: Conectar el escáner al puerto USB y verificar reconocimiento como dispositivo de interfaz humana (HID Keyboard). Paso 2: Ubicar la guía de programación rápida del fabricante (Honeywell, Zebra, Datalogic). Paso 3: Escanear el código de barras de configuración Restore Factory Defaults. Paso 4: Escanear el código de barras de configuración Scan Suffix y a continuación Add Carriage Return / Enter Suffix (0x0D). Paso 5: Abrir Notepad o la aplicación de facturación/inventario y validar que la lectura transmita los dígitos seguidos de un salto de línea automático.', 'Evitar apuntar el haz láser directamente a los ojos del personal técnico o usuarios durante las pruebas.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-090', 'Resolución de fallos en lectores biométricos dactilares y servicio Windows Biometric', 'Paso 1: Abrir la consola de servicios (services.msc) y localizar el servicio Servicio biométrico de Windows (WbioSrvc). Paso 2: Detener el servicio, limpiar la lente o sensor del lector con paño de microfibra seco y volver a iniciar el servicio. Paso 3: En el Administrador de Dispositivos, desinstalar el dispositivo biométrico marcando Eliminar software de controlador. Paso 4: Descargar el paquete de firmware y driver biométrico WHQL del portal del fabricante e instalar como administrador. Paso 5: Abrir Opciones de inicio de sesión de Windows y recalibrar la huella dactilar mediante Windows Hello.', 'Verificar en la directiva de grupo (gpedit.msc) que la directiva Permitir el uso de biometría no esté deshabilitada en la máquina.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-091', 'Diagnóstico de adaptadores de corriente y cargadores de portátiles con falso contacto', 'Paso 1: Desconectar el cargador de la red eléctrica e inspeccionar el cable en busca de pellizcos, cortes o deformaciones en el conector cilíndrico o USB-C. Paso 2: Conectar el cargador a la corriente y medir el voltaje continuo (DC) con un multímetro en el extremo del conector; debe entregar entre 19.5V y 20V estables. Paso 3: Mover suavemente el cable cerca del conector mientras se mide el voltaje para detectar fisuras internas en el conductor de cobre. Paso 4: Si hay caída de voltaje a 0V durante la flexión, descartar el cargador inmediatamente por riesgo de cortocircuito. Paso 5: Sustituir con fuente de poder con idéntico voltaje y amperaje igual o superior.', 'Nunca reparar cables de cargadores uniendo cables pelados con cinta aislante; el falso contacto puede dañar el circuito MOSFET de la placa madre.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-092', 'Reparación de bisagras rígidas o carcasas desencajadas en portátiles corporativos', 'Paso 1: Evaluar la rigidez de la bisagra y detener la apertura de la pantalla si se escucha crujido en la carcasa plástica superior (top cover). Paso 2: Retirar el marco frontal del bisel (bezel) utilizando palancas plásticas de apertura sin forzar el panel LCD. Paso 3: Aflojar un cuarto de vuelta la tuerca de ajuste de fricción de la bisagra metálica para reducir la tensión mecánica. Paso 4: Si los soportes roscados de bronce (standoffs) se desprendieron del chasis plástico, reconstruir la base con resina epoxi bicomponente. Paso 5: Reensamblar comprobando que el cable de antena WiFi y el flex eDP de video no queden aprisionados.', 'No ejercer palanca sobre el vidrio o panel LCD para evitar rotura interna del cristal líquido.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-093', 'Sustitución y configuración de tarjetas de red Gigabit PCIe en estaciones de trabajo', 'Paso 1: Apagar la máquina, desconectar el cable de poder y pulsar el botón de encendido para vaciar energía residual. Paso 2: Retirar la tapa lateral del chasis y ubicar una ranura PCIe x1 o PCIe x4 libre. Paso 3: Insertar la tarjeta de red PCIe de 1 Gbps / 2.5 Gbps asegurando el anclaje firme con el tornillo de sujeción al chasis. Paso 4: Encender el equipo, ingresar a Windows y verificar detección en el Administrador de Dispositivos. Paso 5: Configurar en las propiedades avanzadas del controlador: Speed & Duplex en 1.0 Gbps Full Duplex y deshabilitar Energy Efficient Ethernet.', 'Utilizar pulsera antiestática para evitar descargas sobre las ranuras PCIe de la placa madre.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-094', 'Sustitución de unidad de alimentación ininterrumpida (UPS) local ante alarma sonora continua', 'Paso 1: Identificar el tipo de alarma de la UPS; un pitido continuo suele indicar sobrecarga de vatios o batería interna agotada/dañada. Paso 2: Conectar temporalmente los equipos críticos directamente a la toma de pared regulada mientras se reemplaza la UPS. Paso 3: Apagar la UPS defectuosa, desconectar de la pared y retirar la tapa del compartimiento de baterías. Paso 4: Verificar si las baterías selladas de plomo-ácido (VRLA 12V 7Ah/9Ah) presentan sulfatación o abombamiento. Paso 5: Instalar la nueva UPS verificando que la potencia aparente (VA) cubra el 140% de la carga combinada de los equipos conectados.', 'No conectar impresoras láser a salidas con respaldo de batería de UPS pequeñas; el pico de calentamiento del fusor causa sobrecarga inmediata.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-095', 'Diagnóstico de tarjetas gráficas dedicadas con artefactos visuales y error Code 43', 'Paso 1: Revisar si aparecen líneas horizontales, puntos de colores o patrones en pantalla durante el arranque de la BIOS. Paso 2: Si el Administrador de Dispositivos reporta El dispositivo se detuvo debido a un problema (Código 43), desinstalar el driver con DDU en Modo Seguro. Paso 3: Reinstalar la última versión WHQL estable recomendada por el fabricante de la GPU. Paso 4: Inspeccionar físicamente la tarjeta gráfica verificando que los ventiladores giren y los conectores de energía PCIe de 6/8 pines estén firmes. Paso 5: Si los artefactos persisten en la BIOS, aislar el fallo a desoldadura de chip VRAM o GPU por fatiga térmica y reemplazar tarjeta.', 'Verificar que la fuente de poder entregue los rieles de 12V con amperaje suficiente para la tarjeta gráfica instalada.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-096', 'Mantenimiento preventivo y reemplazo de pasta térmica en estaciones de cómputo', 'Paso 1: Monitorear temperaturas basales con HWMonitor o Core Temp; si superan 85°C en reposo o 95°C en carga, programar mantenimiento. Paso 2: Retirar el disipador térmico con cuidado realizando un suave giro horario/antihorario para despegar la pasta seca sin arrancar la CPU del socket. Paso 3: Limpiar la superficie de la CPU y la base de cobre del disipador con alcohol isopropílico y papel libre de pelusa hasta dejarlas como espejo. Paso 4: Aplicar una gota del tamaño de un guisante de pasta térmica no conductora de alto rendimiento (ej. Arctic MX-4 / Noctua NT-H1). Paso 5: Reinstalar el disipador aplicando presión uniforme en cruz y verificar descenso de temperatura a 35°C-45°C en reposo.', 'No aplicar exceso de pasta térmica para evitar desbordes sobre los componentes superficiales (SMD) de la placa base.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-097', 'Configuración de doble y triple monitor en estaciones financieras mediante MST Hubs', 'Paso 1: Conectar el adaptador DisplayPort Multi-Stream Transport (MST) Hub al puerto DisplayPort 1.4 de la estación o tarjeta de video. Paso 2: Conectar cada monitor a las salidas del hub utilizando cables DisplayPort certificados. Paso 3: En el menú OSD de cada monitor, verificar que la opción DisplayPort 1.2/1.4 MST esté habilitada. Paso 4: En Windows, presionar Windows + P y seleccionar Extender pantalla; organizar la disposición espacial y escala de cada pantalla. Paso 5: Comprobar que el ancho de banda del canal DP soporte la resolución combinada (ej. tres pantallas 1080p a 60 Hz).', 'Los puertos HDMI convencionales y adaptadores pasivos no soportan tecnología MST para pantallas independientes encadenadas.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-098', 'Detección y reparación de bandejas de lectura óptica o unidades DVD bloqueadas', 'Paso 1: Apagar el equipo y localizar el pequeño orificio de expulsión de emergencia manual en el panel frontal de la unidad óptica. Paso 2: Insertar un clip metálico extendido en el orificio y presionar firmemente hasta que la bandeja salga unos milímetros. Paso 3: Extraer la bandeja suavemente con la mano y retirar cualquier disco atascado o restos de etiquetas desprendidas. Paso 4: Inspeccionar la pequeña correa elástica de tracción del motor de apertura; si está estirada o con grasa, limpiarla o reemplazarla. Paso 5: Reconectar la energía y probar la expulsión electrónica mediante el botón frontal y el comando Expulsar en Windows.', 'No forzar la bandeja jalándola bruscamente cuando el engranaje esté trabado para no romper los dientes del mecanismo.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-099', 'Reemplazo de batería de celda CMOS CR2032 ante pérdida recurrente de fecha y BIOS', 'Paso 1: Si la máquina muestra advertencias CMOS Battery Low, Date and Time Not Set o pierde el orden de arranque al apagar de la toma. Paso 2: Desconectar el cable de poder de la máquina y abrir la cubierta del equipo. Paso 3: Localizar la pila botón de litio CR2032 de 3V en la placa base y presionar la pestaña metálica de retención para extraerla. Paso 4: Insertar una pila CR2032 nueva verificando que el polo positivo (+) quede orientado hacia arriba. Paso 5: Encender el equipo, ingresar al setup de BIOS/UEFI (tecla F2 o Supr), ajustar fecha/hora actual, perfil XMP/EXPO y orden de arranque de disco.', 'Manipular la pila sosteniéndola por el borde para no descargarla con los dedos.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-100', 'Pruebas de carga y estrés de CPU y GPU para descartar fallos de silicio o throttling severo', 'Paso 1: Instalar la herramienta de diagnóstico OCCT o Prime95 en un entorno de pruebas controlado. Paso 2: Ejecutar prueba de estrés de CPU Small FFTs monitoreando temperaturas de todos los núcleos y frecuencia de reloj con HWiNFO. Paso 3: Si la frecuencia cae drásticamente (thermal throttling), verificar que el ventilador y la bomba de refrigeración líquida funcionen correctamente. Paso 4: Si se produce pantalla azul con código WHEA_UNCORRECTABLE_ERROR o reinicio instantáneo, diagnosticar degradación de silicio o voltaje insuficiente de la fuente. Paso 5: Generar informe de estabilidad tras superar 30 minutos de estrés continuo sin errores computacionales.', 'Supervisar constantemente las temperaturas durante la prueba; detener de inmediato si cualquier núcleo supera los 100°C.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-101', 'Diagnóstico de cámaras web y micrófonos USB en salas de conferencias no detectados', 'Paso 1: Desconectar el cable USB de la cámara de videoconferencia y probar en un puerto USB 3.0 directo sin concentrador intermedio. Paso 2: En Configuración de Windows > Privacidad y seguridad > Cámara, validar que Acceso a la cámara y Permitir que las aplicaciones accedan a la cámara estén ACTIVADOS. Paso 3: En el Administrador de Dispositivos, verificar que la cámara no aparezca con signo de exclamación amarillo; si aparece, actualizar driver UVC. Paso 4: En Microsoft Teams / Zoom, ingresar a Configuración de Dispositivos y seleccionar el micrófono y altavoz USB como predeterminados. Paso 5: Efectuar llamada de prueba de eco para confirmar sincronización de audio y video sin retardo.', 'Evitar conectar barras de videoconferencia 4K a puertos USB 2.0 (color negro); requieren el ancho de banda de USB 3.0 (color azul).', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-102', 'Limpieza mecánica y desoxidación de puertos USB-C con pelusa o suciedad acumulada', 'Paso 1: Apagar por completo el portátil o teléfono y retirar cualquier cable conectado. Paso 2: Con una lupa y linterna, inspeccionar el interior del puerto USB-C para verificar si hay pelusa comprimida en el fondo que impide el acople completo. Paso 3: Utilizar una sonda plástica o mondadientes de madera no conductor para extraer con sumo cuidado la pelusa sin tocar la lengüeta central de pines. Paso 4: Aplicar un disparo corto de aire comprimido seco en ángulo para expulsar partículas residuales. Paso 5: Conectar el cargador USB-C y comprobar que el conector haga clic firme y se inicie la carga rápida a 65W/100W.', 'NUNCA utilizar agujas metálicas, clips o clips metálicos para raspar el puerto USB-C; causará cortocircuito destructivo en los pines VBUS.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-103', 'Restablecimiento y reprogramación de teclados numéricos externos USB en contabilidad', 'Paso 1: Comprobar si la tecla Bloq Num (Num Lock) está activada; si está apagada, las teclas funcionarán como flechas de navegación en lugar de números. Paso 2: Conectar el teclado numérico en otro puerto USB para descartar fallo en el puerto host. Paso 3: En el Administrador de Dispositivos, expandir Dispositivos de interfaz de usuario y desinstalar cualquier dispositivo USB compuesto con advertencia. Paso 4: Reiniciar el equipo para que Windows recargue el controlador estándar hidusb.sys. Paso 5: Probar escritura en Excel validando tanto el separador decimal (punto o coma según configuración regional de Windows).', 'Verificar en Configuración Regional de Windows si el separador decimal corresponde al estándar corporativo contable.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-104', 'Verificación de integridad física y reemplazo de cables HDMI/DisplayPort en salas de juntas', 'Paso 1: Inspeccionar los conectores metálicos de los extremos en busca de pines doblados, sulfatados o conectores flojos en la carcasa plástica. Paso 2: Si la imagen en el televisor o proyector parpadea al mover el cable en la canaleta, desconectar y probar con cable de repuesto directo. Paso 3: Para tiradas mayores a 10 metros, verificar que se use cable HDMI con fibra óptica activa (AOC) con los extremos Source y Display conectados correctamente. Paso 4: Fijar el cable a la mesa o proyector con bridas de velcro para evitar que la tracción mecánica dañe el puerto del televisor. Paso 5: Validar resolución 4K a 60 Hz y transferencia de audio digital hacia los altavoces de la sala.', 'Los cables HDMI ópticos AOC son unidireccionales; conectar el extremo Display en la fuente causará pantalla negra sin señal.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-105', 'Procedimiento de preservación y desmontaje de equipos expuestos a sobretensión eléctrica', 'Paso 1: No encender el equipo bajo ninguna circunstancia si hubo olor a quemado, humo o chispa durante tormenta eléctrica. Paso 2: Desconectar el equipo de la toma de corriente y trasladar a la mesa de trabajo de laboratorio. Paso 3: Retirar la fuente de poder y abrir el chasis para inspeccionar visualmente condensadores inflados, pistas de cobre quemadas o integrados chamuscados. Paso 4: Extraer la unidad de almacenamiento (SSD o HDD) y conectarla a una estación de lectura forense aislada para verificar si los datos sobrevivieron. Paso 5: Emitir dictamen técnico de daño eléctrico para la compañía de seguros y dar de baja componentes siniestrados.', 'Riesgo de descarga eléctrica residual en condensadores primarios de la fuente de poder; no desarmar la caja de la fuente.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-106', 'Diagnóstico de ruidos anormales o vibración en ventiladores de chasis y lubricación', 'Paso 1: Abrir el chasis del computador mientras está apagado e inspeccionar con linterna si algún cable choca con las aspas de los ventiladores. Paso 2: Girar con el dedo cada ventilador; si se siente fricción, resistencia o juego axial en el rodamiento, desmontar el ventilador. Paso 3: En ventiladores tipo sleeve bearing con tapón trasero de goma, levantar el sello y aplicar una micro-gota de aceite sintético ligero para rodamientos. Paso 4: En ventiladores con rodamientos sellados o aspas rotas, reemplazar por un ventilador PWM de 120 mm / 140 mm de 4 pines. Paso 5: Encender el equipo y verificar velocidad por RPM en BIOS y ausencia de zumbidos mecánicos.', 'No aplicar lubricantes tipo WD-40 soluble en ventiladores de cómputo; resecará el rodamiento y atraerá suciedad rápidamente.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-107', 'Reemplazo y calibración de panel táctil (touchpad) en portátiles corporativos', 'Paso 1: Desconectar la batería interna del portátil antes de manipular los cables de cinta flex del touchpad. Paso 2: Retirar la batería interna que usualmente cubre los tornillos de fijación del touchpad en el chasis superior. Paso 3: Desconectar el cable plano FFC tirando de la pestaña del conector ZIF con delicadeza. Paso 4: Desatornillar el soporte metálico e instalar el nuevo touchpad asegurando una separación perimétrica simétrica de 1 mm. Paso 5: Reconectar la batería, encender la máquina y calibrar la sensibilidad y gestos multitoque en el software de control Synaptics/Precision Touchpad.', 'Los conectores ZIF son sumamente frágiles; levantar la pestaña plástica con excesiva fuerza inutilizará la conexión en la placa madre.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-108', 'Diagnóstico y reasignación de tarjetas PCIe de expansión bloqueadas por conflictos IRQ', 'Paso 1: Si al agregar una tarjeta de captura, tarjeta de sonido o controladora RAID el sistema se congela al arrancar. Paso 2: Ingresar a la BIOS/UEFI del servidor o workstation y revisar el apartado Advanced > PCI Subsystem Settings. Paso 3: Comprobar si la ranura PCIe seleccionada comparte líneas de comunicación con el slot M.2 NVMe primario. Paso 4: Cambiar la tarjeta física a una ranura PCIe gobernada por el chipset secundario o por el Socket 2 de CPU. Paso 5: Desactivar dispositivos integrados en placa no utilizados (ej. puerto serie COM, audio onboard) para liberar líneas de interrupción IRQ.', 'Consultar el manual de arquitectura de la placa base para conocer la distribución exacta de carriles PCIe entre CPU y Chipset.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-109', 'Detección y mitigación de bucles de red Spanning Tree Protocol (STP loop) en switches', 'Paso 1: Si los switches presentan parpadeo frenético sincronizado en todos los LEDs y la red se satura al 100%. Paso 2: Conectar consola serie al switch core o switch de distribución y ejecutar show spanning-tree o show log. Paso 3: Localizar el puerto que genera cambios continuos de topología (Topology Change Notification - TCN). Paso 4: Desconectar el cable UTP que generó el puenteo físico entre dos rosetas o dos switches no gestionados instalados por usuarios. Paso 5: Habilitar en los puertos de acceso de borde el comando spanning-tree bpduguard enable y spanning-tree portfast.', 'Nunca desactivar Spanning Tree globalmente en la infraestructura de switches para evitar caídas totales por tormentas de broadcast.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-110', 'Caída de puerta de enlace predeterminada y conmutación de gateway mediante VRRP/HSRP', 'Paso 1: Ejecutar ping continuo al gateway corporativo (ej. ping 192.168.1.1 -t) para verificar pérdida total de paquetes. Paso 2: Conectarse por consola al router de respaldo y verificar el estado del protocolo de redundancia: show vrrp o show standby. Paso 3: Si el router primario está caído, forzar la transición a estado Master/Active ajustando la prioridad VRRP superior a 110. Paso 4: En las estaciones de trabajo, vaciar la tabla ARP local con el comando arp -d * en cmd como administrador. Paso 5: Validar que el tráfico hacia internet y sedes remotas fluya a través de la dirección IP virtual del gateway compartido.', 'Verificar que las contraseñas de autenticación y los timers de hello/dead en ambos routers sean rigurosamente idénticos.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-111', 'Conmutación de enlace de contingencia 4G/LTE tras caída del enlace troncal de fibra óptica', 'Paso 1: Comprobar las luces de estado LOS (Loss of Signal) y PON en el módem/ONT del proveedor de fibra óptica. Paso 2: En el firewall perimetral (FortiGate, Palo Alto, pfSense), verificar el estado de la interfaz WAN1 e iniciar failover a WAN2 (módem 4G). Paso 3: Si la conmutación automática SD-WAN no operó, cambiar la distancia administrativa de la ruta por defecto hacia la interfaz de backup. Paso 4: Habilitar políticas de conformación de tráfico (traffic shaping) para priorizar ERP y correo, limitando streaming y descargas masivas. Paso 5: Abrir ticket de incidente crítico con el operador del ISP reportando el ID de circuito troncal.', 'El enlace 4G de contingencia suele tener ancho de banda limitado; es mandatorio restringir el tráfico recreativo.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-112', 'Resolución de conflictos de dirección IP estática duplicada mediante rastreo ARP', 'Paso 1: Si una máquina muestra Mensaje de conflicto: Otra máquina en la red tiene la misma dirección IP. Paso 2: Ejecutar arp -a <IP_conflictiva> en una estación diferente para obtener la dirección MAC del dispositivo usurpador. Paso 3: Identificar al fabricante de la MAC consultando el registro OUI (ej. mediante web macvendors.com). Paso 4: En el switch de borde, ejecutar show mac address-table address <MAC> para ubicar el switch y el puerto físico exacto. Paso 5: Apagar temporalmente el puerto del switch causante o reconfigurar el equipo infractor con DHCP dinámico.', 'Mantener documentada la reserva de rangos de direcciones estáticas fuera del scope asignado al servidor DHCP.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-113', 'Configuración de Calidad de Servicio (QoS) y marcado DSCP para tráfico Teams y Zoom', 'Paso 1: En el controlador de dominio, crear una GPO para marcar los paquetes de audio de Teams con DSCP valor 46 (Expedited Forwarding - EF). Paso 2: Marcar los paquetes de video de Teams con DSCP valor 34 (Assured Forwarding - AF41). Paso 3: En los switches y routers de la red, habilitar la inspección de confianza QoS con mls qos trust dscp o qos trust. Paso 4: Configurar colas de baja latencia (Priority Queue) para el tráfico clasificado como EF en las interfaces de salida hacia internet. Paso 5: Validar con Wireshark que los paquetes UDP en puertos 50000-50019 lleven la cabecera DSCP correspondiente.', 'Si los switches intermedios no tienen habilitado QoS trust, pueden sobreescribir la marca DSCP a cero (Best Effort).', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-114', 'Diagnóstico de error de negociación de certificados TLS/SSL en clientes VPN corporativos', 'Paso 1: Revisar el log del cliente VPN (FortiClient, AnyConnect, GlobalProtect) buscando mensajes TLS Handshake Failed o Certificate Unknown. Paso 2: Abrir certmgr.msc en la máquina local y verificar si el certificado de la Autoridad Certificadora (CA) raíz corporativa está en Entidades de certificación raíz de confianza. Paso 3: Si el certificado expiró, descargar el nuevo paquete de certificados desde el portal de PKI interno e importarlo. Paso 4: Verificar que la fecha y hora del sistema operativo estén rigurosamente sincronizadas mediante w32tm /resync. Paso 5: Reconectar el cliente VPN y validar establecimiento del túnel IPsec o SSL en puerto 443 o 10443.', 'Un desajuste de más de 3 minutos en el reloj local causará rechazo automático de la validación criptográfica del certificado.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-115', 'Certificación y crimpado de conectores RJ45 dañados según el estándar ANSI/TIA-568-B', 'Paso 1: Cortar el extremo dañado del cable de red UTP Cat 6 y retirar 2.5 cm de la chaqueta exterior sin cortar los hilos internos. Paso 2: Desenredar los pares y ordenarlos según el código de colores TIA-568-B: Blanco/Naranja, Naranja, Blanco/Verde, Azul, Blanco/Azul, Verde, Blanco/Marrón, Marrón. Paso 3: Cortar los hilos rectos a una longitud de 1.4 cm e introducirlos en el conector RJ45 asegurando que la chaqueta ingrese bajo la uña de fijación. Paso 4: Prensar con la ponchadora crimpadora de impacto hasta escuchar el seguro completo de las cuchillas doradas. Paso 5: Conectar ambos extremos a un analizador/certificador de red (Fluke) y comprobar continuidad y ausencia de pares cruzados.', 'No destrenzar los pares más de 1.3 cm desde la chaqueta para preservar la cancelación de ruido electromagnético.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-116', 'Diagnóstico de alta latencia y pérdida de paquetes en enlaces WAN mediante MTR y PingPlotter', 'Paso 1: Ejecutar la herramienta pathping <IP_Destino> o mtr -r -c 100 <IP_Destino> desde la estación afectada. Paso 2: Analizar los saltos (hops) intermedios identificando en qué nodo específico comienza el porcentaje de pérdida de paquetes (Packet Loss > 1%). Paso 3: Comprobar si el salto problemático corresponde a la red interna, al router de borde del ISP o al carrier troncal. Paso 4: Si la pérdida ocurre en la salida del router local, verificar saturación de la interfaz con show interface y descartar colisiones o drops por buffer. Paso 5: Adjuntar el reporte MTR con hora exacta y trazabilidad al ticket de escalamiento con el proveedor ISP.', 'Diferenciar entre pérdida de paquetes por control de plano ICMP rate-limiting de routers intermedios y descarte real de tráfico transitado.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-117', 'Corrección de cortes en access points WiFi por interferencia de canal o roaming agresivo', 'Paso 1: Realizar escaneo de radiofrecuencia en la zona con analizador Wi-Fi (inSSIDer o WiFi Analyzer) midiendo RSSI y relación señal/ruido (SNR). Paso 2: En la banda de 2.4 GHz, fijar únicamente los canales limpios 1, 6 u 11 sin solapamiento con ancho de 20 MHz. Paso 3: En la banda de 5 GHz, seleccionar canales limpios evitando frecuencias DFS si la oficina queda cerca de radares o aeropuertos. Paso 4: En el controlador inalámbrico (WLC), ajustar la potencia de transmisión de los APs para permitir traslape del 15% al 20% entre celdas. Paso 5: En el adaptador del cliente en Windows, ajustar Roaming Aggressiveness en nivel Medio-Bajo para evitar saltos innecesarios.', 'Colocar la potencia de los APs al 100% genera problemas de celda oculta y asimetría de transmisión con los portátiles.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-118', 'Habilitación y configuración de nuevos puntos de red en patch panels y switches PoE', 'Paso 1: Identificar el puerto disponible en el patch panel de la sala de comunicaciones correspondiente a la toma de pared numerada. Paso 2: Ponchar el cable UTP Cat 6 en el bloque IDC posterior siguiendo el mapa TIA-568-B con ponchadora de impacto 110. Paso 3: Conectar un latiguillo (patch cord) certificado desde el patch panel hacia un puerto libre en el switch de acceso. Paso 4: En el switch, asignar la VLAN correspondiente: interface gig 1/0/15 -> switchport mode access -> switchport access vlan 20. Paso 5: Habilitar portfast y verificar entrega de energía PoE 802.3af/at si el punto de red conectará un teléfono IP o cámara.', 'Verificar el presupuesto total de energía PoE (PoE Power Budget) del switch antes de activar nuevos dispositivos de alto consumo.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-119', 'Diagnóstico de puertos de switch en estado err-disable por detección de tormenta broadcast', 'Paso 1: Conectarse al switch mediante SSH y ejecutar show interfaces status err-disabled para identificar puertos caídos. Paso 2: Ejecutar show log para determinar la causa raíz del bloqueo (storm-control, bpduguard, port-security o loopback-detection). Paso 3: Si fue provocado por tormenta de broadcast, investigar el dispositivo conectado en esa toma (posible tarjeta de red dañada o switch casero). Paso 4: Una vez desconectado el equipo conflictivo, reiniciar el puerto ejecutando shutdown seguido inmediatamente de no shutdown. Paso 5: Opcionalmente configurar errdisable recovery cause all con un intervalo de recuperación de 300 segundos.', 'No rehabilitar el puerto sin desconectar previamente el dispositivo origen de la tormenta de paquetes.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-120', 'Resolución de agotamiento del pool de concesiones DHCP en redes departamentales', 'Paso 1: En la consola de administración DHCP de Windows Server o router, revisar el porcentaje de utilización del ámbito (Scope). Paso 2: Si el scope está al 100% de ocupación, identificar equipos inactivos mediante el listado de concesiones activas. Paso 3: Reducir el tiempo de concesión (Lease Duration) de 8 días a 8 horas en redes con alta rotación o redes Wi-Fi. Paso 4: Si la saturación es por crecimiento de usuarios, ampliar la máscara de subred (ej. cambiar de /24 a /23) o agregar un superscope. Paso 5: Ejecutar netsh dhcp server scope <subred> show clients y purgar concesiones expiradas.', 'Modificar la máscara de subred requiere actualizar simultáneamente la interfaz del gateway y rutas en el firewall.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-121', 'Desbloqueo y auditoría de reglas de firewall perimetral corporativo para aplicaciones críticas', 'Paso 1: Identificar la dirección IP origen, dirección IP destino, puerto de transporte (TCP/UDP) y protocolo de la aplicación bloqueada. Paso 2: Consultar los logs de tráfico descartado (Deny/Drop logs) en el firewall perimetral mediante filtro de IP de la estación. Paso 3: Elaborar la solicitud de cambio (RFC) especificando justificación comercial, criticidad y vigencia de la apertura. Paso 4: Crear la política de seguridad con principio de menor privilegio, restringiendo origen/destino específicos en lugar de abrir Any/Any. Paso 5: Probar conectividad desde la estación con PowerShell: Test-NetConnection -ComputerName <IP_Servidor> -Port <Puerto>.', 'Nunca autorizar reglas permisivas con Any como destino sin la aprobación expresa del oficial de seguridad CISO.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-122', 'Depuración de errores de proxy web y fallos en script automático PAC corporativo', 'Paso 1: Si el navegador muestra Mensaje: Configurando el servidor proxy o No se puede conectar con el servidor proxy. Paso 2: Abrir Opciones de Internet > Conexiones > Configuración de LAN y verificar la URL del script PAC (ej. http://proxy.empresa.local/wpad.dat). Paso 3: Probar la descarga manual del archivo PAC desde el navegador para descartar caída del servidor web interno que lo aloja. Paso 4: Abrir el archivo wpad.dat en un editor y validar la sintaxis de la función FindProxyForURL(url, host). Paso 5: En cmd, ejecutar netsh winhttp import proxy source=ie y reiniciar el servicio de cliente web.', 'Validar que las excepciones de proxy (bypasses) incluyan las direcciones IP locales y subredes internas RFC 1918.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-123', 'Diagnóstico de sesiones RDP congeladas por MTU incorrecta o fragmentación de paquetes', 'Paso 1: Si el Escritorio Remoto inicia sesión pero la pantalla se congela inmediatamente al cargar el fondo de escritorio. Paso 2: Probar el tamaño de MTU sin fragmentación con el comando: ping <IP_Servidor> -f -l 1472. Paso 3: Si se produce el mensaje Es necesario fragmentar el paquete pero se ha establecido DF, reducir el tamaño en pasos de 10 bytes hasta que responda. Paso 4: Calcular la MTU óptima (tamaño que responde + 28 bytes de cabecera IP/ICMP) y aplicarla en la interfaz de red con netsh interface ipv4 set subinterface "Ethernet" mtu=1400 store=persistent. Paso 5: Reconectar RDP y verificar fluidez gráfica continua.', 'La fragmentación en túneles VPN causa descarte silencioso de paquetes RDP grandes de video.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-124', 'Aislamiento de VLAN departamental por fallo de encapsulación 802.1Q en enlace troncal', 'Paso 1: Si todos los equipos de un departamento pierden conectividad mientras que otros departamentos funcionan con normalidad. Paso 2: Conectarse al switch y revisar el estado del enlace troncal (Trunk): show interfaces trunk. Paso 3: Comprobar la lista de VLANs permitidas en el troncal (VLANs allowed on trunk) y confirmar que la VLAN afectada figure en la lista. Paso 4: Si la VLAN no está permitida, agregarla mediante el comando switchport trunk allowed vlan add <VLAN_ID>. Paso 5: Validar que la interfaz VLAN (SVI) en el router o switch capa 3 esté en estado Up/Up con su dirección IP de gateway configurada.', 'No ejecutar switchport trunk allowed vlan <id> sin la palabra clave add, de lo contrario reemplazará todas las VLANs activas cortando la red.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-125', 'Desactivación de adaptadores túnel IPv6 Teredo o 6to4 causantes de retardos en DNS', 'Paso 1: Si el equipo experimenta retrasos de 5 a 10 segundos antes de abrir cualquier página web o recurso corporativo. Paso 2: Ejecutar ipconfig /all y verificar si existen adaptadores virtuales con prefijos 2001:0:: (Teredo) o fe80::. Paso 3: En PowerShell como administrador, ejecutar Get-NetTeredoState y evaluar si está intentando enrutar tráfico sobre IPv6 no operativo. Paso 4: Deshabilitar el túnel Teredo ejecutando Set-NetTeredo -Type Disabled y desactivar 6to4 con Set-Net6to4Configuration -State Disabled. Paso 5: Configurar la preferencia de IPv4 sobre IPv6 en el registro de Windows con valor 0x20 en DisabledComponents y reiniciar.', 'No desmarcar IPv6 en las propiedades de la tarjeta de red en entornos con Exchange o controladores de dominio modernos.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-126', 'Diagnóstico de caídas VPN por bloqueo de puertos IPsec UDP 500 y 4500 en routers caseros', 'Paso 1: Si el usuario teletrabajador recibe Error 809 o El túnel L2TP/IPsec no pudo conectarse desde la red de su hogar. Paso 2: Explicar al usuario cómo acceder a la consola de administración de su router de proveedor residencial (192.168.1.1). Paso 3: Verificar que la opción IPsec Passthrough o VPN Passthrough esté activada en la sección de seguridad/firewall del router. Paso 4: En Windows, agregar la clave de registro DWORD AssumeUDPEncapsulationContextOnSendRule con valor 2 en HKLM\SYSTEM\CurrentControlSet\Services\PolicyAgent. Paso 5: Reiniciar la máquina del teletrabajador y validar conexión sin desconexiones.', 'La modificación del registro de Windows requiere reiniciar el equipo para que el subsistema IPsec aplique la regla.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-127', 'Caída de servidores DNS corporativos y activación inmediata de reenviadores (forwarders)', 'Paso 1: Si los usuarios no pueden resolver nombres de host internos (ej. erp.empresa.local) ni navegar a sitios web. Paso 2: Probar resolución local en el servidor DNS: nslookup erp.empresa.local 127.0.0.1. Paso 3: Si el servicio DNS Server está detenido, iniciarlo con net start DNS o Restart-Service DNS en PowerShell. Paso 4: Si el servidor principal colapsó físicamente, cambiar en el servidor DHCP los punteros DNS primario y secundario hacia el DC2. Paso 5: En el servidor DNS secundario, verificar que los reenviadores públicos (ej. 1.1.1.1, 8.8.8.8) estén configurados y activos.', 'Verificar la replicación de zonas integradas en Active Directory antes de forzar cambios manuales de registros SOA.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-128', 'Falla en puntos de acceso inalámbrico PoE por insuficiencia de potencia en switch de borde', 'Paso 1: Si un access point WiFi se reinicia en bucle o apaga sus radios de 5 GHz aleatoriamente. Paso 2: Conectarse al switch PoE y ejecutar show power inline para consultar el consumo de vatios por puerto y la potencia total disponible. Paso 3: Comprobar la clasificación del AP; puntos de acceso Wi-Fi 6 requieren estándar PoE+ 802.3at (30W) y no PoE estándar 802.3af (15.4W). Paso 4: En la configuración de la interfaz del switch, forzar la asignación de potencia máxima con power inline auto max 30000. Paso 5: Si el switch agotó su fuente PoE, migrar los APs a puertos de un switch con presupuesto disponible o intercalar inyectores PoE+ certificados.', 'Puntos de acceso sub-alimentados reducen la potencia de sus antenas y provocan desconexiones masivas de clientes.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-129', 'Configuración de portal cautivo para red WiFi de invitados y depuración de redirección HTTP', 'Paso 1: Si los visitantes se conectan a la red WiFi Invitados pero no les aparece automáticamente la página de términos y condiciones. Paso 2: Verificar que el servidor DNS asignado a la red de invitados resuelva solicitudes iniciales y no bloquee el puerto 53 UDP. Paso 3: En el controlador inalámbrico, verificar que la lista de control de acceso (Pre-Auth ACL) permita tráfico hacia la IP del portal cautivo en puerto 80/443. Paso 4: Solicitar al usuario que ingrese en el navegador a una página web HTTP sin cifrar (ej. http://neverssl.com) para forzar la intercepción. Paso 5: Confirmar la aceptación de políticas y verificar la concesión de acceso por 4 horas.', 'Los navegadores modernos bloquean redirecciones forzadas si el usuario intenta abrir directamente un sitio HTTPS con HSTS estricto.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-130', 'Diagnóstico de atenuación excesiva y suciedad en conectores de fibra óptica con VFL', 'Paso 1: Si un enlace de fibra óptica entre switches o edificios muestra flapping continuo o degradación a 100 Mbps. Paso 2: Desconectar los conectores LC/SC de los transceptores SFP con precaución y acoplar el lápiz localizador visual de fallos (VFL / láser rojo). Paso 3: Inspeccionar el extremo opuesto del patch cord y bandejas de distribución ODF para verificar si la luz roja es continua o si hay quiebre de filamento. Paso 4: Limpiar las férulas de los conectores ópticos utilizando una pluma limpiadora de fibra de un clic (One-Click Cleaner) de 1.25 mm / 2.5 mm. Paso 5: En el switch, verificar los niveles de potencia óptica recibida mediante el comando show interfaces transceivers detail; deben estar dentro del umbral Rx (-3 dBm a -14 dBm).', 'PELIGRO: NUNCA mirar directamente al extremo de un conector de fibra óptica o puerto SFP encendido; la radiación infrarroja no visible daña la retina.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-131', 'Mitigación de interferencias de radiofrecuencia en bandas 2.4 GHz y 5 GHz en oficinas', 'Paso 1: Si los usuarios experimentan cortes de audio en llamadas y lentitud en un área específica a pesar de tener señal excelente. Paso 2: Utilizar un analizador de espectro de RF (ej. Wi-Spy / Chanalyzer) para identificar emisores de interferencia no-WiFi (hornos microondas, cámaras inalámbricas analógicas, teléfonos DECT). Paso 3: Reubicar el punto de acceso WiFi a una distancia mínima de 3 metros de electrodomésticos o ductos de ventilación metálicos. Paso 4: Deshabilitar la transmisión en 2.4 GHz en zonas de alta densidad e inducir a los clientes a 5 GHz mediante Band Steering. Paso 5: Validar que la métrica de ruido de piso (Noise Floor) sea inferior a -90 dBm.', 'Superficies espejadas y ventanales con película térmica de aluminio reflejan las microondas de radio distorsionando la señal.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-132', 'Pérdida de conectividad LAN por deshabilitación accidental de adaptador en directivas', 'Paso 1: Si un equipo de cómputo muestra el icono de red con un globo terráqueo o mensaje No conectado a ninguna red. Paso 2: Abrir ncpa.cpl y verificar si el adaptador Conexión de área local o Ethernet aparece en estado Deshabilitado (gris). Paso 3: Hacer clic derecho y seleccionar Habilitar; si solicita permisos de administrador, comprobar si una directiva GPO deshabilitó la interfaz. Paso 4: En PowerShell como administrador, ejecutar Get-NetAdapter y Enable-NetAdapter -Name "Ethernet" -Confirm:$false. Paso 5: Ejecutar gpupdate /force para cerciorarse de que no haya una política conflictiva de seguridad de red revirtiendo el estado.', 'Validar que el usuario no tenga herramientas de virtualización (VirtualBox, VMware) con adaptadores puente que desactiven el adaptador físico.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-133', 'Respaldo y restauración en caliente de archivos de configuración (.cfg) en switches corporativos', 'Paso 1: Establecer sesión SSH con el switch de borde o distribución utilizando credenciales administrativas de nivel 15. Paso 2: Para switches Cisco, ejecutar copy running-config tftp: especificando la IP del servidor TFTP y nombre de archivo con fecha y sede. Paso 3: Para switches HP/Aruba, ejecutar copy running-config sftp://usuario@servidor/ruta/backup.cfg. Paso 4: En caso de falla catastrófica y reemplazo de hardware por RMA, conectar consola al equipo nuevo y cargar la imagen base de firmware compatible. Paso 5: Restaurar la configuración mediante copy tftp: running-config y ejecutar write memory / copy run start para persistir.', 'Verificar siempre que el archivo de configuración respaldado no contenga contraseñas en texto plano desprotegidas.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-134', 'Diagnóstico de cortes en telefonía IP SIP provocados por inspección SIP ALG en routers', 'Paso 1: Si los teléfonos IP corporativos experimentan llamadas mudas en un sentido (audio unidireccional) o llamadas que se caen a los 30 segundos exactos. Paso 2: Acceder al router perimetral o firewall que conecta la sede con la central telefónica PBX. Paso 3: Localizar la opción SIP ALG (Application Layer Gateway) o SIP Helper en el menú de NAT/Firewall. Paso 4: Deshabilitar por completo SIP ALG en el router ejecutando en consola (ej. en FortiGate: set default-voip-alg-mode kernel-helper-based). Paso 5: Reiniciar los teléfonos IP de la oficina para que regeneren el registro SIP en puerto 5060 con la dirección IP pública sin alteración de cabeceras.', 'SIP ALG modifica erróneamente las cabeceras SDP de los paquetes SIP, causando que el tráfico RTP de audio se desvíe a IPs inexistentes.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-135', 'Auditoría y rastreo de tomas de red no identificadas mediante generador de tonos y sonda', 'Paso 1: Conectar el generador de tonos (toner / pollo) a la toma de pared RJ45 de la oficina en modo Tone continuo. Paso 2: Dirigirse al rack de comunicaciones del piso y retirar los organizadores frontales de patch cords. Paso 3: Pasar la sonda inductiva receptora por los conectores del patch panel escuchando la amplificación acústica máxima. Paso 4: Al identificar el puerto exacto, conectar el probador de cable para confirmar mapeo pin a pin de los 8 conductores. Paso 5: Etiquetar la toma de pared y el puerto del patch panel según el estándar de nomenclatura del edificio (ej. P02-R01-PP03-D14).', 'No inyectar tono en puertos de switch que tengan PoE activo sin utilizar un generador de tonos protegido contra voltaje.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-136', 'Corrección de fallos en resolución NetBIOS y WINS en sedes que no resuelven servidores', 'Paso 1: Si los usuarios pueden acceder a recursos por dirección IP (ej. \\192.168.10.50) pero no por nombre corto (ej. \\SRV-FILES). Paso 2: Abrir cmd y ejecutar nbtstat -R para purgar la tabla de nombres de caché NetBIOS local. Paso 3: Ejecutar nbtstat -RR para enviar paquetes de liberación y registro de nombres hacia el servidor WINS corporativo. Paso 4: En la configuración de TCP/IP avanzada del adaptador, seleccionar Habilitar NetBIOS a través de TCP/IP. Paso 5: Validar que el sufijo DNS principal de la empresa esté configurado para que la resolución fallback a DNS FQDN complete la búsqueda.', 'La resolución basada en NetBIOS emite broadcasts; en redes modernas es preferible migrar a nombres FQDN con DNS.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-137', 'Monitoreo de saturación de ancho de banda y bloqueo de tráfico anómalo en el firewall', 'Paso 1: Si el enlace a internet de la sede alcanza el 100% de ocupación de forma sostenida y la navegación colapsa. Paso 2: Abrir el analizador de tráfico en tiempo real (Flow / NetFlow / sFlow) en el firewall perimetral. Paso 3: Ordenar por volumen de bytes consumidos e identificar las IPs locales con mayor tasa de transferencia. Paso 4: Verificar si el tráfico corresponde a descargas no autorizadas, torrents P2P o sincronizaciones masivas personales. Paso 5: Aplicar regla de bloqueo inmediata para la IP o categoría de tráfico y aislar la estación de la red para su escaneo antivirus.', 'Verificar si el consumo proviene de una actualización legítima de Windows Update antes de bloquear el equipo del usuario.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-138', 'Verificación y cambio de orden de vinculación de tarjetas de red en Windows Server', 'Paso 1: Si un servidor con múltiples tarjetas de red (ej. LAN de producción y LAN de backup) envía tráfico de consulta DNS por la interfaz incorrecta. Paso 2: En PowerShell como administrador, ejecutar Get-NetIPInterface para consultar la métrica de interfaz (InterfaceMetric) de cada adaptador. Paso 3: Asignar una métrica menor a la tarjeta de producción para que tenga mayor prioridad en la tabla de enrutamiento de Windows. Paso 4: Ejecutar Set-NetIPInterface -InterfaceAlias "Produccion" -InterfaceMetric 10 y Set-NetIPInterface -InterfaceAlias "Backup" -InterfaceMetric 50. Paso 5: Ejecutar route print y validar que la ruta 0.0.0.0 apunte al gateway de la tarjeta de producción.', 'Métricas mal configuradas provocan que las sesiones de gestión remota se desvíen por la red aislada de copias de seguridad.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-139', 'Desbloqueo masivo de cuentas de dominio Active Directory provocado por directivas GPO', 'Paso 1: Abrir la consola de PowerShell en un Controlador de Dominio como administrador de dominio. Paso 2: Ejecutar Search-ADAccount -LockedOut para listar todas las cuentas de usuario bloqueadas en la infraestructura. Paso 3: Ejecutar Search-ADAccount -LockedOut | Unlock-ADAccount para desbloquear las cuentas afectadas simultáneamente. Paso 4: Abrir el Visor de Eventos de Seguridad y filtrar por el Event ID 4740 (A user account was locked out) para identificar la estación de origen (Caller Computer Name). Paso 5: Conectarse a la estación origen y limpiar credenciales obsoletas almacenadas en tareas programadas, servicios o Credential Manager.', 'No desbloquear cuentas sin identificar y mitigar la máquina que genera los intentos fallidos en bucle; se bloquearán nuevamente en minutos.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-140', 'Falla de inicio de sesión único (SSO) en Azure AD / Entra ID por caducidad de token SAML', 'Paso 1: Si los usuarios reciben el error AADSTS50011 o AADSTS700016 al ingresar a aplicaciones corporativas federadas. Paso 2: Acceder al portal de Microsoft Entra ID > Aplicaciones empresariales y localizar el aplicativo afectado. Paso 3: En el apartado Inicio de sesión único > Certificado de firma de SAML, verificar la fecha de vencimiento del certificado. Paso 4: Si está expirado, generar un nuevo certificado de firma SAML y cargar el archivo de metadatos o certificado en el panel de la aplicación externa. Paso 5: Marcar el nuevo certificado como Activo en Entra ID y probar autenticación en ventana privada.', 'La rotación de certificados SAML debe coordinarse con el administrador de la aplicación externa para evitar caída del servicio.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-141', 'Renovación e importación de certificados digitales de facturación electrónica y firma DIAN', 'Paso 1: Obtener el archivo contenedor de certificado digital (.pfx o .p12) provisto por la entidad certificadora autorizada. Paso 2: Abrir certmgr.msc en la estación del usuario contable o servidor de facturación. Paso 3: En la carpeta Personal > Certificados, hacer clic derecho > Todas las tareas > Importar. Paso 4: Seleccionar el archivo, marcar la opción Marcar esta clave como exportable si se requiere respaldo, e ingresar la contraseña de seguridad. Paso 5: En el software contable (Siigo, SAP, World Office), asociar el nuevo serial de certificado y emitir factura de prueba a la DIAN.', 'Custodiar de forma estrictamente confidencial la contraseña del certificado digital; tiene plena validez jurídica tributaria.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-142', 'Procedimiento urgente de revocación de accesos y cierre de sesiones por desvinculación', 'Paso 1: Recibir la notificación formal del área de Gestión Humana con la fecha y hora exacta de retiro del colaborador. Paso 2: En Active Directory local, deshabilitar la cuenta con Disable-ADAccount -Identity <usuario> y moverla a la OU de Usuarios Desvinculados. Paso 3: En Microsoft Entra ID / M365, revocar todas las sesiones activas con Revoke-AzureADUserAllRefreshToken. Paso 4: Ocultar el buzón de la lista de direcciones global (GAL) y convertir el buzón a Buzón Compartido (Shared Mailbox) para no perder el histórico. Paso 5: Reasignar la licencia de Microsoft 365 y bloquear de inmediato las llaves VPN y tarjetas de acceso físico.', 'Ejecutar la revocación de forma inmediata para prevenir exfiltración de información confidencial o sabotaje de sistemas.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-143', 'Desincronización de contraseña entre el equipo portátil sin conexión y el Active Directory', 'Paso 1: Si el usuario cambió su contraseña en el portal web de autoservicio o en la oficina, pero el portátil no reconoce la nueva clave en casa. Paso 2: Solicitar al usuario que inicie sesión en el equipo portátil utilizando su contraseña ANTERIOR que aún reside en la caché de credenciales local. Paso 3: Una vez en el escritorio de Windows, conectar la sesión de VPN corporativa para establecer conectividad IP con los controladores de dominio. Paso 4: Presionar Ctrl + Alt + Supr y seleccionar Bloquear este equipo; luego desbloquear ingresando la NUEVA contraseña. Paso 5: Verificar que la caché local de credenciales se actualice correctamente desconectando la VPN y reiniciando.', 'No intentar formatear el equipo; la conexión VPN con la sesión abierta sincronizará el hash Kerberos automáticamente.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-144', 'Restablecimiento de segundo factor MFA ante pérdida o daño del teléfono corporativo', 'Paso 1: Validar rigurosamente la identidad del solicitante mediante llamada con cámara o confirmación directa de su jefe inmediato. Paso 2: Acceder al centro de administración de Microsoft Entra ID > Usuarios > Métodos de autenticación. Paso 3: Seleccionar Exigir nuevo registro de autenticación multifactor (Re-register MFA) y revocar sesiones MFA existentes. Paso 4: Generar un Pase de acceso temporal (Temporary Access Pass - TAP) con vigencia de 4 horas y entregarlo de manera segura al usuario. Paso 5: Guiar al usuario para que inicie sesión con el TAP y configure la aplicación Microsoft Authenticator en su nuevo dispositivo móvil.', 'Nunca desactivar el requerimiento de MFA a nivel global o individual de forma permanente; utilizar siempre pases temporales TAP.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-145', 'Diagnóstico y mitigación de solicitudes repetitivas de segundo factor MFA en Microsoft 365', 'Paso 1: Si Outlook o Teams solicitan validación de código MFA cada 2 horas interfiriendo con la operación del usuario. Paso 2: En el centro de administración de Entra ID, revisar las directivas de Acceso Condicional (Conditional Access Policies) aplicadas al usuario. Paso 3: Verificar la configuración de Frecuencia de inicio de sesión (Sign-in frequency) y asegurar que esté establecida en 7 o 14 días. Paso 4: En la máquina del usuario, desconectar y volver a conectar la cuenta corporativa en Configuración de Windows > Cuentas > Acceso a trabajo o escuela. Paso 5: Borrar credenciales de Office en el Administrador de Credenciales y reiniciar aplicaciones.', 'Directivas de acceso condicional mal estructuradas pueden sobreponerse y generar bucles de desafío de autenticación continuos.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-146', 'Configuración y enrolamiento de llaves físicas de seguridad FIDO2 (YubiKey) en Windows', 'Paso 1: Insertar la llave de seguridad FIDO2 en el puerto USB de la estación de trabajo y verificar reconocimiento por Windows. Paso 2: Acceder a Configuración > Cuentas > Opciones de inicio de sesión > Llave de seguridad y hacer clic en Administrar. Paso 3: Tocar el sensor táctil de la llave e ingresar o configurar un código PIN numérico de seguridad personal. Paso 4: En el portal corporativo mysecurityinfo.microsoft.com, hacer clic en Agregar método > Llave de seguridad > Dispositivo USB. Paso 5: Seguir el asistente en pantalla tocando la llave cuando el LED parpadee y validar inicio de sesión sin contraseña (Passwordless).', 'Instruir al usuario sobre la confidencialidad del PIN; si se equivoca 8 veces consecutivas, la llave FIDO2 se bloqueará definitivamente.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-147', 'Asignación y auditoría de permisos de lectura y escritura en carpetas compartidas SMB (AGDLP)', 'Paso 1: Si un usuario requiere acceso a una carpeta compartida en el servidor de archivos corporativo. Paso 2: No asignar el usuario directamente a la lista de control de acceso (ACL) de la carpeta; aplicar la metodología AGDLP. Paso 3: Identificar el grupo de seguridad de dominio local correspondiente (ej. DL_Finanzas_Modificar) asignado en los permisos NTFS. Paso 4: Agregar al usuario al grupo global correspondiente a su cargo (ej. GG_Analistas_Financieros) en Active Directory. Paso 5: Solicitar al usuario que cierre e inicie sesión en Windows para renovar su token Kerberos y comprobar acceso al recurso compartido.', 'La asignación directa de usuarios a carpetas compartidas corrompe la gobernanza de accesos y dificulta auditorías de seguridad.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-148', 'Recuperación de acceso a volumen cifrado con BitLocker tras cambio de hardware o BIOS', 'Paso 1: Si al encender el equipo Windows muestra la pantalla azul de BitLocker solicitando la clave de recuperación de 48 dígitos. Paso 2: Identificar el Identificador de clave de recuperación (Recovery Key ID de 8 caracteres alfanuméricos) que aparece en pantalla. Paso 3: Acceder a la consola de Microsoft Entra ID o Active Directory Users and Computers y buscar el objeto de equipo correspondiente. Paso 4: En la pestaña BitLocker Recovery, contrastar el ID y copiar la clave numérica de 48 dígitos dividida en 8 bloques de 6 números. Paso 5: Digitar la clave en la pantalla de bloqueo, acceder al sistema y suspender y reactivar BitLocker para reasociar el chip TPM.', 'Verificar rigurosamente la identidad del usuario y número de serie del equipo antes de dictar la clave de BitLocker.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-149', 'Generación de contraseña de administrador local temporal mediante LAPS para soporte', 'Paso 1: Cuando el técnico requiera privilegios de administrador local en una estación de trabajo sin usar credenciales de dominio. Paso 2: Abrir la consola de Windows LAPS en Active Directory o consultar la consola de Microsoft Intune para el dispositivo específico. Paso 3: Copiar la contraseña aleatoria compleja autogenerada por la directiva LAPS para la cuenta de administrador local. Paso 4: Iniciar sesión en la estación utilizando la sintaxis .\Administrador y la contraseña provista por LAPS. Paso 5: Ejecutar la tarea técnica requerida y forzar la rotación inmediata de la contraseña con Reset-LapsPassword al finalizar.', 'Nunca compartir la contraseña de LAPS por canales abiertos ni dejarla anotada en notas adhesivas en el equipo.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-150', 'Desbloqueo y actualización de contraseñas para cuentas de servicio de Windows críticas', 'Paso 1: Si un servicio de fondo crítico (ej. servicio de sincronización, backup o cola de impresión) no inicia con error 1069. Paso 2: Abrir Active Directory Users and Computers y verificar si la cuenta de servicio (ej. svc_backup) está bloqueada o expirada. Paso 3: Desbloquear la cuenta y establecer una nueva contraseña de alta entropía según la política de seguridad corporativa. Paso 4: En el servidor donde corre el servicio, abrir services.msc > Propiedades del servicio > pestaña Iniciar sesión y actualizar la contraseña. Paso 5: Iniciar el servicio y verificar en el Visor de Eventos que no se registren fallos de logon (Event ID 4625).', 'Actualizar la contraseña en todas las instancias y tareas programadas donde esté configurada la cuenta antes de reiniciar el servicio.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-151', 'Gestión y rotación de certificados SSL/TLS para servidores web IIS y Apache internos', 'Paso 1: Generar la solicitud de firma de certificado (CSR) desde el Administrador de IIS o mediante OpenSSL especificando el FQDN exacto y SANs. Paso 2: Enviar la CSR a la Entidad Certificadora interna de la empresa (Microsoft CA) y emitir el certificado x509 en formato CRT o PFX. Paso 3: Importar el certificado en el almacén Equipo local > WebHosting o Personal del servidor web. Paso 4: En IIS, editar los Enlaces del sitio (Bindings), seleccionar el puerto 443 HTTPS y asociar el nuevo certificado SSL. Paso 5: Probar desde un navegador cliente que la conexión cargue con candado verde sin advertencias de certificado no confiable.', 'La rotación de certificados debe planificarse al menos 15 días antes de la fecha de caducidad para evitar interrupción de servicios.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-152', 'Corrección de error Kerberos por desfase de reloj (clock skew) entre estación y dominio', 'Paso 1: Si el usuario no puede iniciar sesión en el dominio y recibe El sistema no puede autenticarlo debido a una diferencia de tiempo. Paso 2: Verificar la hora y zona horaria de la estación de trabajo y compararla con la hora del Controlador de Dominio principal (PDC Emulator). Paso 3: En cmd como administrador, ejecutar w32tm /config /syncfromflags:domhier /update para forzar la jerarquía de dominio. Paso 4: Ejecutar net stop w32time seguido de net start w32time y w32tm /resync /force. Paso 5: Validar que el desfase temporal sea menor a 1 segundo y proceder con el inicio de sesión regular.', 'El protocolo Kerberos 5 rechaza por diseño de seguridad cualquier solicitud de ticket con desfase mayor a 300 segundos (5 minutos).', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-153', 'Procedimiento de contención y aislamiento de cuentas con alerta de compromiso o viaje imposible', 'Paso 1: Recibir alerta del centro de operaciones de seguridad (SOC) o Entra Identity Protection por inicio de sesión de riesgo alto. Paso 2: Inmediatamente deshabilitar la cuenta del usuario en Active Directory y revocar tokens de autenticación activos en la nube. Paso 3: Contactar al usuario por vía telefónica directa confirmada para verificar si realizó el intento de acceso desde la ubicación reportada. Paso 4: Si se confirma el compromiso, restablecer la contraseña a un valor seguro y forzar re-enrolamiento completo de factores MFA. Paso 5: Auditar en el log de auditoría si se crearon reglas de reenvío de correo maliciosas en el buzón del usuario.', 'Revisar siempre la bandeja de entrada y reglas de transporte de Outlook; los atacantes suelen crear reglas para ocultar sus acciones.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-154', 'Aprovisionamiento acelerado de cuentas de usuario para nuevas sedes corporativas', 'Paso 1: Recibir la matriz de vinculación del personal aprobada con nombres completos, número de cédula, cargo y departamento. Paso 2: Ejecutar el script corporativo de aprovisionamiento en PowerShell New-CorpUser.ps1 leyendo los datos desde archivo CSV validado. Paso 3: Asignar la Unidad Organizativa (OU) correspondiente a la nueva sede geográfica. Paso 4: Asignar membresía a los grupos base de seguridad, cuota de buzón de correo y carpeta compartida de departamento. Paso 5: Generar el archivo de bienvenida seguro con credenciales iniciales de un solo uso que obligan al cambio de clave en el primer inicio.', 'Validar que ningún nombre de cuenta (sAMAccountName) colisione con cuentas existentes en el bosque de Active Directory.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-155', 'Depuración de errores de acceso denegado HTTP 401 y 403 en aplicaciones intranet corporativas', 'Paso 1: Si los usuarios acceden a una web interna y reciben Error 401 Unauthorized o 403 Forbidden a pesar de ingresar credenciales correctas. Paso 2: En el servidor IIS, verificar que en el módulo Autenticación esté habilitada Autenticación de Windows y deshabilitada Autenticación anónima. Paso 3: En los proveedores de autenticación, verificar el orden de negociación: NTLM y Negotiate (Kerberos). Paso 4: Si se utiliza Kerberos, verificar que los nombres de entidad de servicio (SPN) estén correctamente registrados con setspn -L <cuenta_servicio>. Paso 5: En el navegador del cliente, agregar la URL de la intranet a la zona Sitios de confianza o Intranet local.', 'La falta de registro del SPN adecuado provoca fallas intermitentes de autenticación Kerberos que degradan a NTLM o fallan.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-156', 'Restablecimiento de credenciales almacenadas corruptas en Credential Manager de Windows', 'Paso 1: Si el usuario recibe continuamente solicitudes emergentes de clave al abrir carpetas de red, Outlook o impresoras. Paso 2: Abrir el Administrador de Credenciales de Windows (cmdkey /list o buscar en Panel de Control). Paso 3: En el apartado Credenciales de Windows, inspeccionar las entradas bajo Credenciales genéricas y de dominio. Paso 4: Eliminar las entradas obsoletas vinculadas al servidor de archivos o cuentas corporativas seleccionando Quitar. Paso 5: Reiniciar el proceso explorer.exe o reiniciar el equipo, acceder nuevamente al recurso e ingresar la clave actual marcando Recordar.', 'Eliminar credenciales genéricas no afecta la contraseña real del usuario en el Directorio Activo.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-157', 'Configuración de directivas de Acceso Condicional en Entra ID para exigir equipos Intune', 'Paso 1: En el portal de administración de Microsoft Entra ID, dirigirse a Protección > Acceso Condicional. Paso 2: Crear o editar la directiva Requiere dispositivo compatible para acceso a recursos corporativos. Paso 3: En Asignaciones > Usuarios, incluir a todos los usuarios exceptuando la cuenta de emergencia Break-Glass. Paso 4: En Controles de acceso > Conceder, seleccionar Conceder acceso y marcar Requerir que el dispositivo esté marcado como compatible. Paso 5: En la máquina del usuario, verificar en la aplicación Portal de Empresa (Intune Company Portal) que el estado figure como Compatible.', 'SIEMPRE mantener una cuenta de emergencia Break-Glass excluida de las directivas de acceso condicional para evitar bloqueos totales.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-158', 'Corrección de problemas en escritorios virtuales (VDI) por perfil de usuario temporal', 'Paso 1: Si al iniciar sesión en un host VDI o Remote Desktop Session Host (RDSH), Windows muestra Ha iniciado sesión con un perfil temporal. Paso 2: Solicitar al usuario que cierre la sesión (no solo desconectar la ventana de RDP). Paso 3: En el servidor de perfiles (FSLogix o Roaming Profiles), verificar si el archivo de disco virtual VHD/VHDX del usuario quedó bloqueado por otra sesión. Paso 4: Si el archivo está tomado, cerrar los identificadores abiertos en el servidor de archivos mediante Administración de equipos > Carpetas compartidas > Archivos abiertos. Paso 5: En el registro del servidor VDI, eliminar la clave de perfil con sufijo .bak en HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList.', 'Cualquier archivo guardado en el escritorio mientras se esté en una sesión de perfil temporal se perderá definitivamente al cerrar sesión.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-159', 'Delegación de control administrativo en Unidades Organizativas (OU) de Active Directory', 'Paso 1: Si un técnico de soporte nivel 1 requiere permisos para restablecer claves de una sede sin ser Administrador de Dominio. Paso 2: Abrir Active Directory Users and Computers, hacer clic derecho sobre la OU de la sede y seleccionar Delegar control. Paso 3: Agregar el grupo de seguridad de técnicos de soporte correspondiente (ej. GG_Soporte_Nivel1). Paso 4: Seleccionar las tareas comunes a delegar: Restablecer contraseñas de usuario y forzar el cambio en el siguiente inicio de sesión y Desbloquear cuentas. Paso 5: Finalizar el asistente y comprobar desde la estación del técnico que pueda operar sobre esa OU sin privilegios elevados.', 'Aplicar el principio de mínimo privilegio; nunca otorgar privilegios de Domain Admins a personal de mesa de ayuda.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-160', 'Actualización y desbloqueo de cuenta de sincronización híbrida Microsoft Entra Connect', 'Paso 1: Si los cambios en usuarios locales de Active Directory no se reflejan en la nube de Microsoft 365. Paso 2: Conectarse al servidor donde corre Microsoft Entra Connect (DirSync) y abrir el Synchronization Service Manager. Paso 3: Revisar el registro de operaciones; si aparece el estado Stopped-server-error o Invalid-credentials, revisar la cuenta de sincronización. Paso 4: En PowerShell, ejecutar Import-Module ADSync seguido de Get-ADSyncScheduler para comprobar el intervalo de sincronización (30 min). Paso 5: Si la sincronización está pausada, forzar ciclo delta inmediato con Start-ADSyncSyncCycle -PolicyType Delta.', 'No forzar un ciclo inicial (Initial Sync) sin justificación técnica; en empresas grandes puede tardar horas y consumir CPU.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-161', 'Solución a rechazo de tarjetas inteligentes corporativas por listas de revocación CRL', 'Paso 1: Si al insertar la tarjeta inteligente en el lector para iniciar sesión, Windows arroja El certificado fue revocado o No se pudo comprobar el estado de revocación. Paso 2: Abrir certutil -verifyctl -urlcache para examinar la caché local de listas de revocación de certificados (CRL). Paso 3: Probar la conectividad HTTP/LDAP hacia los puntos de distribución de CRL (CDP) especificados en el certificado de la CA. Paso 4: Forzar la actualización de la lista de revocación ejecutando certutil -pulse o vaciar la caché CRL con certutil -urlcache crl delete. Paso 5: Reintentar el inicio de sesión con la tarjeta inteligente y corroborar aceptación del PIN.', 'Si el servidor web que publica la lista CRL está fuera de servicio, todos los inicios de sesión por Smart Card fallarán por seguridad.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-162', 'Configuración de directivas de auditoría de inicios de sesión fallidos en servidores Windows', 'Paso 1: Abrir la consola de Administración de directivas de grupo (gpmc.msc) y editar la directiva de seguridad de controladores de dominio. Paso 2: Dirigirse a Configuración de seguridad > Directivas avanzadas de auditoría > Inicio/Cierre de sesión. Paso 3: Habilitar la auditoría de Auditoría de inicio de sesión marcando Aciertos y Errores. Paso 4: Habilitar la auditoría de Auditoría de bloqueo de cuentas en Errores. Paso 5: En los servidores, ejecutar gpupdate /force y validar en el Visor de Eventos de Seguridad la aparición de los eventos 4624 y 4625.', 'Monitorear el tamaño máximo configurado para el registro de eventos de Seguridad para evitar sobreescritura prematura de evidencias.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-163', 'Desbloqueo de usuarios restringidos por directivas de horario de trabajo (Logon Hours)', 'Paso 1: Si un usuario recibe el error Su cuenta tiene restricciones de tiempo que le impiden iniciar sesión en este momento. Paso 2: Abrir Active Directory Users and Computers y buscar la cuenta del usuario en su OU respectiva. Paso 3: Ir a Propiedades > pestaña Cuenta y hacer clic en el botón Horas de inicio de sesión (Logon Hours). Paso 4: Revisar la matriz de horarios permitidos y contrastar con la solicitud de horas extras o trabajo en fin de semana autorizada por su jefatura. Paso 5: Pintar en azul las casillas horarias autorizadas, aplicar los cambios y confirmar que el usuario pueda iniciar sesión inmediatamente.', 'Exigir siempre autorización por escrito del jefe de área antes de ampliar los horarios de inicio de sesión de un colaborador.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-164', 'Creación y enrolamiento de certificados de correo seguro S/MIME para firma digital', 'Paso 1: En el portal web de la CA interna o consola certmgr.msc, solicitar un nuevo certificado con la plantilla Firma y cifrado S/MIME. Paso 2: Comprobar que el Subject Alternative Name (SAN) del certificado coincida con la dirección de correo electrónico corporativa del usuario. Paso 3: En Microsoft Outlook, ir a Archivo > Opciones > Centro de confianza > Configuración del Centro de confianza > Seguridad del correo electrónico. Paso 4: En Correo electrónico cifrado, hacer clic en Configuración y seleccionar el certificado S/MIME importado para firma y cifrado. Paso 5: Enviar un correo de prueba firmado digitalmente y verificar que el destinatario observe el icono de la escarapela roja certificada.', 'Respaldar el archivo PFX del certificado con su clave privada en lugar seguro; si se pierde, no se podrán descifrar correos antiguos.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-165', 'Asignación controlada de licencias Microsoft 365 mediante pertenencia a grupos de seguridad', 'Paso 1: En el portal de administración de Microsoft Entra ID, crear o seleccionar el grupo de seguridad de licenciamiento (ej. LIC_M365_E3_Estándar). Paso 2: En la pestaña Licencias del grupo, asignar la suscripción deseada activando únicamente las aplicaciones autorizadas (Exchange, Teams, Office). Paso 3: Para licenciar a un usuario nuevo, agregarlo como miembro del grupo de seguridad correspondiente en lugar de asignar licencia directa. Paso 4: En la consola de auditoría de licencias, comprobar que el estado de asignación figure como Heredado (Inherited) sin errores de conflicto. Paso 5: Validar que el buzón de Exchange Online y aplicaciones de Office queden aprovisionados en un lapso de 15 minutos.', 'Evitar mezclar asignaciones directas y asignaciones basadas en grupos para no duplicar el consumo de licencias contratadas.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-166', 'Resincronización de token criptográfico SafeNet / ePass para firma electrónica en PDFs', 'Paso 1: Si al firmar un documento en Adobe Acrobat o portal jurídico el token físico no solicita PIN o no aparece en la lista de certificados. Paso 2: Abrir la consola de administración del cliente criptográfico (SafeNet Authentication Client / ePass2003 Manager). Paso 3: Comprobar si el token es detectado en el puerto USB y si el certificado en su interior figura como válido y no revocado. Paso 4: Si el software no detecta el token, reiniciar el servicio de tarjeta inteligente SCardSvr en cmd: net stop SCardSvr && net start SCardSvr. Paso 5: En Adobe Acrobat, ir a Preferencias > Firmas > Identidades y certificados de confianza y registrar el módulo PKCS#11 del token.', 'Si el usuario introduce el PIN erróneamente en 3 ocasiones consecutivas, el token entrará en estado bloqueado y requerirá PUK de desbloqueo.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-167', 'Auditoría y revocación de permisos heredados en carpetas confidenciales de finanzas', 'Paso 1: Localizar la carpeta compartida confidencial en el servidor de archivos (ej. D:\Compartido\Finanzas\Presupuestos). Paso 2: Abrir Propiedades > pestaña Seguridad > Opciones avanzadas. Paso 3: Si la carpeta hereda permisos de la raíz, hacer clic en Deshabilitar herencia y seleccionar Convertir los permisos heredados en permisos explícitos. Paso 4: Retirar los grupos genéricos como Usuarios del dominio, Todos o Usuarios autenticados de la lista de acceso. Paso 5: Dejar configurados exclusivamente los grupos de seguridad autorizados (ej. DL_Finanzas_Lectura y DL_Finanzas_Modificar) y Administradores.', 'Siempre convertir los permisos heredados antes de deshabilitar la herencia; eliminarlos todos causará bloqueo inmediato para todos los usuarios.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-168', 'Desbloqueo y gestión de credenciales de acceso a consolas fuera de banda (iLO/iDRAC)', 'Paso 1: Si el acceso web a la interfaz iDRAC o iLO del servidor rechaza las credenciales del técnico o bloqueó la IP por intentos fallidos. Paso 2: Conectarse por cable directo al puerto de gestión dedicado del servidor y verificar si responde a ping en su IP estática. Paso 3: Conectarse mediante SSH a la interfaz de comandos iDRAC/iLO utilizando la cuenta de servicio de contingencia o clave predeterminada del chasis. Paso 4: Ejecutar comando racadm racreset para reiniciar el controlador de gestión sin afectar el sistema operativo del servidor. Paso 5: Si la cuenta está bloqueada, restablecerla con racadm user set -i 2 -p <NuevaClave> y comprobar ingreso web.', 'El reinicio de la controladora iDRAC/iLO no apaga ni reinicia el sistema operativo de producción del servidor.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-169', 'Desbloqueo de ejecutables de producción bloqueados por falsos positivos en EDR corporativo', 'Paso 1: Si el motor de antivirus/EDR (Defender for Endpoint, CrowdStrike, SentinelOne) bloquea o pone en cuarentena un ejecutable productivo. Paso 2: Obtener el valor hash SHA-256 del archivo bloqueado desde la consola central de seguridad o con PowerShell: Get-FileHash <Ruta> -Algorithm SHA256. Paso 3: Verificar la reputación del hash en VirusTotal y comprobar que el binario provenga de un proveedor comercial legítimo o desarrollo interno firmado. Paso 4: En la consola central del EDR, crear una regla de exclusión o indicador de permiso (Allow Indicator) basada estrictamente en el hash SHA-256. Paso 5: Restaurar el archivo de la cuarentena a su ruta original en la estación y validar ejecución del software.', 'Nunca crear exclusiones amplias de carpetas completas (ej. C:\* o C:\Archivos de programa) para evitar brechas de seguridad.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-170', 'Reparación de caídas y errores fatales en software contable ERP durante exportación de libros', 'Paso 1: Si el software contable (Siigo, World Office, Helisa) arroja excepción de memoria violada al exportar libros oficiales a Excel. Paso 2: Verificar que la estación disponga de al menos 4 GB de memoria RAM libre y cerrar procesos concurrentes. Paso 3: En el directorio de instalación del ERP, ubicar la carpeta temporal (Temp/Export) y purgar archivos temporales residuales (.tmp). Paso 4: Comprobar la integridad de las tablas contables ejecutando la utilidad de mantenimiento y compactación incluida en el aplicativo. Paso 5: Realizar la exportación seleccionando formato texto plano (.csv) o por rangos de fechas trimestrales para reducir la huella de memoria.', 'Realizar un respaldo completo de la base de datos de la empresa antes de ejecutar cualquier herramienta de compactación o reconstrucción.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-171', 'Diagnóstico y resolución de deadlocks y bloqueos transaccionales en bases de datos relacionales', 'Paso 1: Si la aplicación empresarial queda congelada esperando respuesta de la base de datos SQL Server o PostgreSQL. Paso 2: En SQL Server, ejecutar sp_who2 o consultar sys.dm_exec_requests identificando sesiones con blocking_session_id != 0. Paso 3: En PostgreSQL, consultar pg_stat_activity identificando transacciones en estado active con wait_event_type = ''Lock''. Paso 4: Evaluar la consulta que sostiene el bloqueo exclusivo (X-Lock); si es un reporte analítico pesado ejecutado indebidamente en producción, terminar la sesión con KILL <spid> o pg_terminate_backend(pid). Paso 5: Recomendar a los desarrolladores optimizar los niveles de aislamiento y crear índices adecuados para evitar escaneos de tabla completa.', 'Finalizar una transacción crítica de actualización masiva puede requerir un tiempo prolongado de rollback antes de liberar los recursos.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-172', 'Caída de base de datos por saturación de disco y crecimiento del registro de transacciones', 'Paso 1: Si el motor de base de datos se detiene de emergencia o entra en modo Read-Only por falta de espacio en el volumen de datos o logs. Paso 2: En SQL Server, verificar si el archivo .LDF consumió todo el disco; ejecutar BACKUP LOG <BD> TO DISK = ''NUL'' si el modelo es Full sin backup, y luego DBCC SHRINKFILE(<Archivo_Log>, 1024). Paso 3: En PostgreSQL, verificar si los archivos WAL en pg_wal llenaron el disco; comprobar si hay slots de replicación inactivos en pg_replication_slots y eliminarlos. Paso 4: Reubicar archivos secundarios en un nuevo volumen de disco ampliado. Paso 5: Reiniciar el servicio de base de datos y verificar que todas las tablas pasen a estado Online y accesible.', 'Nunca eliminar manualmente los archivos .ldf o archivos de log WAL desde el explorador de Windows; dejará la base de datos en estado sospechoso irrecuperable.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-173', 'Diagnóstico y reejecución de trabajos de copia de seguridad (backup) fallidos en Veeam', 'Paso 1: Abrir la consola de Veeam Backup & Replication y revisar el historial de trabajos en estado Failed o Warning. Paso 2: Hacer doble clic en el trabajo fallido para inspeccionar el registro detallado e identificar si la falla fue por snapshot de VSS, credenciales o almacenamiento lleno. Paso 3: Si el error es Unable to create VSS snapshot, conectarse a la máquina virtual y verificar que los VSS Writers de Windows estén estables con vssadmin list writers. Paso 4: Si el repositorio de respaldo (Backup Repository) no tiene espacio suficiente, purgar copias obsoletas fuera de la política de retención. Paso 5: Reejecutar el trabajo manualmente seleccionando Retry y validar que la copia de seguridad finalice en estado Success.', 'No deshabilitar la coherencia de aplicaciones (Application-Aware Processing) en servidores con Active Directory o SQL Server.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-174', 'Restauración de archivos y carpetas eliminados accidentalmente desde copias de sombra VSS', 'Paso 1: Si un usuario eliminó por error un archivo o sobreescribió una hoja de cálculo crítica en el servidor de archivos. Paso 2: Navegar a la carpeta superior donde residía el archivo, hacer clic derecho y seleccionar Restaurar versiones anteriores. Paso 3: Seleccionar la instantánea (Volume Shadow Copy) correspondiente a la fecha y hora previa al incidente. Paso 4: Hacer clic en Abrir para inspeccionar el contenido de la copia de sombra sin sobreescribir la carpeta actual. Paso 5: Copiar el archivo específico y pegarlo en una ubicación segura; validar con el usuario la integridad de los datos recuperados.', 'No presionar el botón Restaurar directamente si hay otros archivos modificados en la carpeta actual, ya que sobreescribirá todo el directorio.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-175', 'Reparación de autocompletado y regeneración de libreta de direcciones global (GAL) en Outlook', 'Paso 1: Si Outlook no muestra los nuevos empleados en la libreta de direcciones o autocompleta con correos antiguos no válidos. Paso 2: En Outlook, ir a Enviar y recibir > Grupos de envío y recepción > Descargar libreta de direcciones y desmarcar Descargar cambios desde la última vez. Paso 3: Si el error persiste, cerrar Outlook y navegar a %localappdata%\Microsoft\Outlook\Offline Address Books\. Paso 4: Eliminar las subcarpetas con identificadores GUID que contienen los archivos OAB locales corruptos. Paso 5: Iniciar Outlook; la aplicación descargará una copia fresca de la GAL desde el servidor Exchange en un plazo de 5 minutos.', 'Para entradas de autocompletado erróneas individuales, basta con pulsar la X al final de la sugerencia en la barra de destinatarios.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-176', 'Solución a caídas y desconexiones masivas en mensajería empresarial instantánea corporativa', 'Paso 1: Si todos los usuarios pierden conexión simultáneamente con la plataforma de mensajería (Teams, Slack o Mattermost). Paso 2: Consultar la consola de estado de servicios del proveedor (ej. portal de salud de Microsoft 365 Service Health o status.slack.com). Paso 3: Si el incidente es local, verificar la conectividad de salida hacia las URLs y rangos de IP del servicio en puertos 443 TCP y 3478-3481 UDP. Paso 4: Si se utiliza un servidor local (on-premise), conectarse al servidor y reiniciar los servicios de socket y la base de datos Redis/Postgres. Paso 5: Enviar comunicado corporativo a los usuarios confirmando el incidente y el canal de comunicación alternativo provisional.', 'Mantener informados a los usuarios durante caídas masivas para evitar saturación de llamadas en la mesa de ayuda.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-177', 'Reparación de CRM corporativo inoperativo por corrupción de caché local o índices', 'Paso 1: Si los operadores reportan pantalla en blanco o errores JavaScript al cargar fichas de clientes en el sistema CRM web. Paso 2: Solicitar al usuario presionar Ctrl + F5 para forzar la recarga de scripts e imágenes evadiendo la caché del navegador. Paso 3: Si persiste, borrar cookies y datos de almacenamiento local (IndexedDB y LocalStorage) en Configuración de Privacidad del navegador. Paso 4: Probar el acceso desde ventana en modo incógnito; si funciona, deshabilitar extensiones de navegador conflictivas. Paso 5: Si el problema es del servidor, acceder a la base del CRM y reindexar las tablas de clientes y oportunidades de venta.', 'Verificar que el navegador utilizado cumpla con la lista de navegadores homologados por el fabricante del software CRM.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-178', 'Corrección de bloqueos en Microsoft Word al insertar tablas complejas de más de 100 filas', 'Paso 1: Si Word deja de responder al pegar datos extensos desde Excel o al manipular tablas con gran número de filas y columnas. Paso 2: Desactivar la aceleración gráfica por hardware en Word > Archivo > Opciones > Avanzadas > apartado Mostrar. Paso 3: En las propiedades de la tabla, desmarcar Permitir dividir filas entre páginas y desactivar Ajuste de texto alrededor de la tabla. Paso 4: Guardar el documento en formato binario .DOCB o .DOCX limpio para optimizar la estructura interna de XML comprimido. Paso 5: Si el archivo está dañado, abrir Word, seleccionar Archivo > Abrir > Explorar > seleccionar archivo y elegir Abrir y reparar.', 'Documentos extensos con cientos de páginas y tablas pesadas deben segmentarse en documentos maestros para evitar corrupción.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-179', 'Reparación de Adobe Acrobat Reader al congelarse abriendo formularios tributarios o jurídicos', 'Paso 1: Si Acrobat Reader se bloquea al abrir archivos PDF pesados con campos de formulario interactivo o firmas digitales. Paso 2: Abrir Adobe Acrobat Reader e ir a Edición > Preferencias > Seguridad (mejorada) y desactivar Activar modo protegido al iniciar. Paso 3: En el apartado Internet, desmarcar Permitir descarga especulativa en segundo plano. Paso 4: Ir a Ayuda > Reparar instalación de Adobe Acrobat Reader para restaurar librerías DLL y claves de registro dañadas. Paso 5: Actualizar a la última versión acumulativa oficial que corrige vulnerabilidades y fugas de memoria.', 'La desactivación del modo protegido solo debe aplicarse en documentos corporativos de confianza; reactivar cuando sea posible.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-180', 'Corrección de errores de timeout y desconexión en SAP GUI hacia servidores de aplicación', 'Paso 1: Si los usuarios en sedes remotas reportan que SAP GUI se cierra con el mensaje WSAETIMEDOUT o Pérdida de conexión con servidor de mensajes. Paso 2: Abrir el archivo saplogon.ini o el archivo XML de conexiones SAP y verificar que la dirección IP y número de sistema sean correctos. Paso 3: Probar latencia hacia el servidor de aplicación SAP ejecutando ping continuo; una latencia superior a 150 ms causa timeouts. Paso 4: En el archivo services de Windows (C:\Windows\System32\drivers\etc\services), verificar que la línea sapms<SID> 3600/tcp esté presente. Paso 5: En la configuración de red de SAP GUI, activar la opción Conexión de red lenta (Slow connection) para habilitar compresión de datos.', 'La opción de conexión lenta reduce el consumo de ancho de banda y la probabilidad de timeouts en sedes interconectadas por enlaces modestos.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-181', 'Solución para clientes de correo electrónico que no reciben mensajes externos por colas', 'Paso 1: Si el dominio corporativo deja de recibir correos provenientes de remitentes externos (Gmail, clientes, proveedores). Paso 2: Verificar los registros MX públicos del dominio mediante nslookup -type=mx midominio.com y confirmar que apunten a los servidores de correo vigentes. Paso 3: En el servidor de correo o consola antispam perimetral, revisar las colas de mensajes entrantes (Inbound Queues). Paso 4: Si la cola está detenida por saturación de espacio en disco en el servidor de buzones, liberar almacenamiento de inmediato. Paso 5: Comprobar que la IP del servidor de correo no haya sido listada en listas negras internacionales RBL (Spamhaus, Barracuda).', 'Cambios en los registros DNS MX pueden demorar hasta 24 horas en propagarse mundialmente según el TTL configurado.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-182', 'Diagnóstico y reparación de bucles de reinicio o Deshaciendo cambios en Windows Update', 'Paso 1: Si Windows entra en un bucle continuo de reinicio mostrando No pudimos completar las actualizaciones. Deshaciendo cambios. Paso 2: Iniciar el equipo en Modo Seguro con funciones de red o mediante el entorno de recuperación de Windows (WinRE). Paso 3: Abrir cmd como administrador y detener los servicios de actualización: net stop wuauserv && net stop bits && net stop cryptsvc. Paso 4: Renombrar las carpetas de descarga temporal: ren C:\Windows\SoftwareDistribution SoftwareDistribution.old y ren C:\Windows\System32\catroot2 catroot2.old. Paso 5: Reiniciar los servicios con net start wuauserv y ejecutar sfc /scannow para reparar archivos corruptos de sistema.', 'No forzar el apagado manteniendo el botón presionado durante el proceso de desinstalación de parches para no dañar la partición BCD.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-183', 'Mitigación de saturación del 100% de CPU provocada por procesos TiWorker y WmiPrvSE', 'Paso 1: Abrir el Administrador de Tareas y ordenar por columna CPU para identificar el proceso que causa saturación sostenida. Paso 2: Si el culpable es TiWorker.exe / Trustedinstaller, corresponde al instalador de Windows Modules; ejecutar Solucionador de problemas de Windows Update. Paso 3: Si el proceso es WmiPrvSE.exe (WMI Provider Host), abrir el Visor de Eventos > Aplicaciones y servicios > Microsoft > Windows > WMI-Activity > Operativo. Paso 4: Filtrar por eventos de error e identificar el identificador de proceso cliente (ClientProcessId) que satura WMI con consultas anómalas. Paso 5: Detener o reinstalar la aplicación identificada (frecuentemente software de monitorización antiguo o agentes obsoletos).', 'No finalizar por la fuerza el proceso TrustedInstaller mientras esté aplicando modificaciones en el registro de componentes del sistema.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-184', 'Despliegue y distribución controlada de software corporativo mediante SCCM / Intune', 'Paso 1: Empaquetar el instalador del software en formato MSI o crear el paquete Win32 (.intunewin) con los parámetros de instalación silenciosa (ej. /qn /norestart). Paso 2: Probar la instalación silenciosa en una máquina virtual de pruebas ejecutando el instalador bajo el contexto de SYSTEM (utilizando PsExec -s -i cmd.exe). Paso 3: Definir la regla de detección (Detection Rule) comprobando la existencia de la clave de registro del desinstalador o versión del archivo .exe principal. Paso 4: Cargar el paquete a la consola de Intune o SCCM y asignarlo a un grupo piloto de usuarios técnicos para validar telemetría. Paso 5: Tras superar el periodo de evaluación piloto de 48 horas sin incidencias, desplegar de forma escalonada al resto de la organización.', 'Validar rigurosamente la regla de detección; una regla incorrecta causará reintentos continuos de instalación e interrupción al usuario.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-185', 'Solución a fallos de sincronización en OneDrive por errores de ruta larga MAX_PATH', 'Paso 1: Si OneDrive muestra un icono de advertencia rojo y el mensaje El nombre del archivo o la ruta es demasiado largo. Paso 2: Explicar al usuario que la ruta completa del archivo sumada al nombre excede el límite histórico de Windows de 260 caracteres. Paso 3: Solicitar al usuario abreviar los nombres de las carpetas anidadas o mover el archivo a una ubicación más cercana a la raíz de la biblioteca. Paso 4: Habilitar el soporte de rutas largas en Windows mediante directiva GPO o registro: HKLM\SYSTEM\CurrentControlSet\Control\FileSystem -> LongPathsEnabled = 1. Paso 5: Reiniciar OneDrive con onedrive.exe /reset para forzar re-escaneo y validar sincronización exitosa de todos los elementos.', 'A pesar de habilitar LongPathsEnabled en Windows, algunas aplicaciones antiguas de terceros no admiten rutas mayores a 260 caracteres.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-186', 'Recuperación de buzones Outlook con archivo offline OST corrupto mediante ScanPST / ScanOST', 'Paso 1: Cerrar completamente Microsoft Outlook y verificar en el Administrador de Tareas que el proceso outlook.exe no continúe activo. Paso 2: Navegar a la carpeta de Office (ej. C:\Archivos de programa\Microsoft Office\root\Office16) y ejecutar SCANPST.EXE. Paso 3: Hacer clic en Examinar y seleccionar el archivo .OST del usuario ubicado en %localappdata%\Microsoft\Outlook\. Paso 4: Hacer clic en Iniciar para examinar la estructura del archivo y seleccionar Hacer copia de seguridad del archivo escaneado antes de reparar. Paso 5: Hacer clic en Reparar; si el archivo está irreparablemente dañado, renombrarlo a .old e iniciar Outlook para que reconstruya el archivo desde el servidor.', 'El archivo OST es una réplica local; eliminarlo no borra correos del servidor Exchange Online de Microsoft 365.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-187', 'Solución de errores en navegadores web que muestran La conexión no es privada', 'Paso 1: Si al acceder a sitios web corporativos o plataformas SaaS el navegador muestra NET::ERR_CERT_AUTHORITY_INVALID. Paso 2: Hacer clic en el icono del candado con advertencia y examinar los detalles del certificado para identificar la Autoridad Certificadora que lo emitió. Paso 3: Si el emisor es la CA corporativa interna o el firewall de inspección profunda SSL (FortiGate / Palo Alto), verificar su certificado raíz. Paso 4: Abrir certmgr.msc y constatar que el certificado raíz corporativo esté instalado en Entidades de certificación raíz de confianza. Paso 5: Si falta, distribuirlo mediante directiva de grupo GPO o importarlo manualmente en los almacenes de Windows y Firefox.', 'Nunca instruir al usuario a hacer clic en Opciones avanzadas > Continuar al sitio de modo inseguro para sitios externos no corporativos.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-188', 'Configuración y resolución de problemas en clientes SSH y emuladores de terminal (PuTTY)', 'Paso 1: Si el técnico o administrador no puede conectarse por SSH a switches o servidores Linux recibiendo Network error: Connection refused. Paso 2: Verificar mediante ping que el equipo destino responda y que el puerto TCP 22 esté abierto con Test-NetConnection -Port 22. Paso 3: Si el error es Server unexpectedly closed network connection, verificar si el servidor exige cifrados modernos que la versión vieja de PuTTY no soporta. Paso 4: Actualizar PuTTY a la versión más reciente y configurar la llave privada en formato .PPK generada con PuTTYgen. Paso 5: En Connection > SSH > Kex, ajustar el orden de preferencia de algoritmos de intercambio de claves (Diffie-Hellman / Curve25519).', 'No almacenar contraseñas en texto plano en las sesiones guardadas de PuTTY por motivos de seguridad.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-189', 'Optimización y reparación de librerías de tiempo de ejecución Visual C++ y .NET Framework', 'Paso 1: Si un software ERP o contable arroja error al abrir indicando que falta MSVCR120.dll o excepción no controlada en .NET Framework. Paso 2: Descargar el paquete redistribuible oficial de Microsoft Visual C++ All-in-One (versiones 2012, 2013, 2015-2022 tanto x86 como x64). Paso 3: Instalar o ejecutar reparación de cada paquete desde el Panel de Control > Programas y características. Paso 4: Para .NET Framework, ejecutar la herramienta oficial Microsoft .NET Framework Repair Tool para diagnosticar corrupciones de registro. Paso 5: Reiniciar el equipo y ejecutar la aplicación corporativa para comprobar resolución de dependencias.', 'Aplicaciones de 32 bits requieren obligatoriamente las librerías redistribuibles x86, incluso en sistemas operativos de 64 bits.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-190', 'Corrección de errores al imprimir facturas desde navegadores por bloqueo de ventanas pop-up', 'Paso 1: Si el usuario pulsa Imprimir factura en la plataforma web contable o bancaria y no sucede nada. Paso 2: Observar la barra de direcciones del navegador en el extremo derecho en busca del icono de ventana emergente bloqueada. Paso 3: Hacer clic en el icono y marcar Permitir siempre ventanas emergentes y redirecciones de <URL_Plataforma>. Paso 4: En la ventana de previsualización de impresión, verificar que la impresora de facturación esté seleccionada y los márgenes configurados en Ninguno. Paso 5: Desmarcar Encabezados y pies de página para evitar que aparezca la URL y fecha impresa en el comprobante contable.', 'Limpiar la caché del navegador puede restablecer temporalmente los permisos de ventanas emergentes; documentar la excepción.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-191', 'Diagnóstico de servicios de Windows que se detienen con error 1067 inesperado', 'Paso 1: Abrir la consola services.msc e intentar iniciar el servicio que falló; documentar el mensaje exacto de error. Paso 2: Abrir el Visor de Eventos > Registros de Windows > Sistema y filtrar por el origen Service Control Manager (Event ID 7024 o 7034). Paso 3: Abrir el Visor de Eventos > Aplicación para leer la traza del error (Stack Trace) o excepción de software no controlada. Paso 4: Verificar si el servicio requiere una ruta de almacenamiento que ya no existe o un archivo de configuración .ini/.xml corrupto. Paso 5: Restaurar el archivo de configuración desde el respaldo o reinstalar los binarios del servicio mediante la utilidad de mantenimiento.', 'No cambiar la cuenta de inicio de sesión del servicio a Sistema Local sin evaluar los riesgos de seguridad y permisos de red.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-192', 'Reindexación y mantenimiento de catálogos de búsqueda en servidores de archivos Windows', 'Paso 1: Si los usuarios reportan que las búsquedas de archivos en carpetas de red tardan minutos o devuelven resultados incompletos. Paso 2: Conectarse al servidor de archivos y abrir Opciones de indización en el Panel de Control. Paso 3: Hacer clic en Modificar y verificar que las carpetas compartidas de datos estén incluidas en las ubicaciones indizadas. Paso 4: Hacer clic en Opciones avanzadas y presionar el botón Reconstruir para purgar el catálogo de búsqueda dañado. Paso 5: Monitorear en el Administrador de Tareas que el proceso SearchIndexer.exe complete la indexación sin saturar el disco.', 'La reconstrucción del catálogo de indización puede tomar varias horas en volúmenes con millones de archivos; planificar fuera de horario.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-193', 'Procedimiento de contención y limpieza de equipos infectados con troyanos o adware', 'Paso 1: Desconectar inmediatamente el equipo de la red LAN retirando el cable de red y apagando el interruptor de Wi-Fi. Paso 2: Iniciar la estación en Modo Seguro y ejecutar Microsoft Defender Offline para escanear sectores de arranque y memoria física. Paso 3: En el Administrador de Tareas > pestaña Inicio, deshabilitar cualquier proceso no reconocido o con nombres sospechosos aleatorios. Paso 4: En los navegadores web instalados, revisar extensiones y complementos eliminando barras de herramientas o extensiones no homologadas. Paso 5: Ejecutar examen completo con Malwarebytes Enterprise, restablecer contraseñas de red del usuario y reconectar.', 'Si se detectan rastros de ransomware o exfiltración activa, preservar la memoria RAM y notificar de inmediato al equipo CSIRT.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-194', 'Configuración de redirección de carpetas conocidas (Known Folder Move) en OneDrive', 'Paso 1: Si los documentos y escritorio de los usuarios no están respaldados en la nube y residen únicamente en el disco local C:. Paso 2: En el controlador de dominio, configurar la GPO de OneDrive Activar la sincronización silenciosa de carpetas de Windows en OneDrive. Paso 3: En la estación del usuario, abrir la configuración de OneDrive > pestaña Copia de seguridad > Administrar copia de seguridad. Paso 4: Seleccionar las carpetas Escritorio, Documentos e Imágenes y presionar Iniciar copia de seguridad. Paso 5: Confirmar que los iconos cambien a una nube azul o círculo verde indicando sincronización y disponibilidad en la nube.', 'Verificar que el almacenamiento disponible en la cuenta de OneDrive del usuario cubra el tamaño de sus archivos locales.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-195', 'Auditoría y desinstalación de software no homologado o sin licencia en estaciones', 'Paso 1: Ejecutar el script corporativo de inventario Get-WmiObject -Class Win32_Product o consultar el reporte de activos de Endpoint Manager. Paso 2: Identificar programas que no formen parte del catálogo de software estándar corporativo (juegos, torrents, utilitarios no autorizados). Paso 3: Notificar al usuario formalmente sobre la violación de las políticas de uso aceptable de tecnología. Paso 4: Proceder con la desinstalación silenciosa del aplicativo mediante PowerShell: Uninstall-Package o msiexec /x. Paso 5: Generar el informe de cumplimiento de licencias para el departamento jurídico y de auditoría interna.', 'El software no autorizado puede introducir vulnerabilidades de seguridad críticas e incurrir en sanciones legales por piratería.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-196', 'Resolución de conflictos de versiones de Java Runtime Environment (JRE) en portales bancarios', 'Paso 1: Si un aplicativo bancario o gubernamental no abre y exige una versión específica obsoleta de Java (ej. Java 8 update 202). Paso 2: Abrir el Panel de Control de Java > pestaña Java > botón Ver para listar las versiones JRE instaladas en el sistema. Paso 3: En la pestaña Seguridad, agregar la URL exacta del portal bancario en la Lista de excepciones de sitios. Paso 4: En la pestaña Avanzadas, asegurarse de tener habilitados los protocolos TLS 1.2 y TLS 1.3. Paso 5: Si el navegador predeterminado bloquea los applets de Java, configurar el modo IE (Internet Explorer Mode) en Microsoft Edge.', 'Mantener versiones antiguas de Java desactualizadas representa un vector de ataque; aislar su uso estrictamente al portal requerido.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-197', 'Diagnóstico de fallos en generación y firma de archivos XML de nómina electrónica hacia DIAN', 'Paso 1: Si el software de gestión de talento humano arroja rechazo en el envío del lote de nómina electrónica a los servidores de la DIAN. Paso 2: Abrir el archivo XML generado y validarlo contra el esquema XSD oficial de la DIAN utilizando un validador XML. Paso 3: Comprobar que los campos de identificación del empleado (tipo documento, cédula, nombre) no contengan caracteres especiales no permitidos. Paso 4: Verificar que el certificado digital de nómina electrónica no haya expirado y esté correctamente firmado con el algoritmo SHA-256. Paso 5: Reenviar el documento de soporte de nómina corregido y verificar la recepción del código único de documento (CUNE) con estado Aceptado.', 'Los errores de nómina electrónica no subsanados en los plazos legales acarrean sanciones tributarias para la empresa.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-198', 'Corrección de fallos en videollamadas de Microsoft Teams por códecs y aceleración gráfica', 'Paso 1: Si durante las reuniones de Teams la pantalla parpadea en negro o los demás participantes no escuchan el audio del expositor. Paso 2: En Teams, hacer clic en Configuración (...) > General y marcar Deshabilitar aceleración de hardware de GPU. Paso 3: En Configuración > Dispositivos, desactivar Supresión de ruido si la CPU del equipo es de baja potencia para liberar ciclos de procesamiento. Paso 4: Purgar la caché de Teams cerrando la aplicación y eliminando los contenidos de %appdata%\Microsoft\Teams\Cache. Paso 5: Reiniciar Microsoft Teams y efectuar una llamada de prueba para corroborar estabilidad de video a 30 fps.', 'La aceleración por hardware en controladores de video integrados antiguos suele causar congelamiento del hilo gráfico de Teams.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-199', 'Procedimiento de compactación y purga de buzones de correo para usuarios al límite de cuota', 'Paso 1: Si el usuario recibe avisos de Su buzón está casi lleno y no puede enviar nuevos correos por superar los 50 GB / 100 GB. Paso 2: En Outlook, abrir Archivo > Herramientas > Limpieza de buzón e identificar elementos de gran tamaño mayores a 10 MB. Paso 3: Vaciar de forma definitiva la carpeta Elementos eliminados y la carpeta Correo no deseado. Paso 4: Configurar directiva de retención o archivado en línea (Online Archive) en Microsoft 365 para mover correos de más de 2 años al archivo histórico ilimitado. Paso 5: Para clientes IMAP/POP locales, exportar elementos antiguos a un archivo de datos PST local seguro y compactar el buzón.', 'Asegurarse de que el usuario no tenga correos importantes archivados en la carpeta Elementos eliminados antes de purgarla.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-200', 'Verificación de integridad y restauración de consistencia en bases de datos con DBCC CHECKDB', 'Paso 1: Si el motor de base de datos reporta errores de I/O, páginas dañadas (torn pages) o inconsistencias lógicas en índices. Paso 2: En SQL Server Management Studio, programar una ventana de mantenimiento y ejecutar DBCC CHECKDB (''<NombreBD>'') WITH NO_INFOMSGS. Paso 3: Si se detectan errores de consistencia en tablas de usuario, evaluar el nivel mínimo de reparación sugerido. Paso 4: Si se sugiere REPAIR_REBUILD, poner la base de datos en modo monousuario y ejecutar DBCC CHECKDB (''<NombreBD>'', REPAIR_REBUILD). Paso 5: Si se requiere REPAIR_ALLOW_DATA_LOSS, detener la operación de inmediato y proceder con la restauración desde el último respaldo limpio.', 'REPAIR_ALLOW_DATA_LOSS elimina páginas corruptas destruyendo datos transaccionales; debe ser el último recurso tras agotar respaldos.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-201', 'Procedimiento de actualización de firmware y agentes SNMP en servidores físicos y switches', 'Paso 1: Descargar el paquete de actualización de firmware certificado por el fabricante y verificar el checksum SHA-256 oficial. Paso 2: Verificar la compatibilidad de versiones con el hardware actual y comprobar que no existan dependencias de saltos intermedios de versión. Paso 3: Programar ventana de mantenimiento en horario no laboral notificando a los administradores de sistemas. Paso 4: Conectar el servidor o switch a una UPS con respaldo garantizado para impedir cortes eléctricos durante el flasheo de la memoria ROM. Paso 5: Aplicar la actualización mediante la interfaz web de gestión o consola CLI, esperar el reinicio automático y verificar la versión operativa.', 'Un corte de energía durante el flasheo de firmware dejará el equipo en estado inutilizado (bricked) requiriendo reemplazo de placa.', 1) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-202', 'Reparación de perfil de usuario corrupto de Windows que inicia con cuenta temporal TEMP', 'Paso 1: Si al iniciar sesión el usuario observa un escritorio vacío con fondo negro y el aviso Ha iniciado sesión con un perfil temporal. Paso 2: Iniciar sesión con una cuenta de administrador local para no alterar el perfil del usuario. Paso 3: Abrir regedit y navegar a HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ProfileList. Paso 4: Localizar la clave del SID del usuario que tiene la extensión .bak y la clave homónima sin extensión. Paso 5: Renombrar la clave sin extensión a .corrupt y retirar la extensión .bak de la clave original; verificar que ProfileImagePath apunte a C:\Users\<Usuario> y reiniciar.', 'No mover ni eliminar la carpeta de datos en C:\Users\<Usuario> para evitar pérdida de documentos y descargas del colaborador.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-203', 'Configuración y verificación de scripts de inicio de sesión (logon scripts) en Sysvol de dominio', 'Paso 1: Si las unidades de red o impresoras corporativas no se asignan automáticamente al iniciar sesión los usuarios. Paso 2: Acceder a la carpeta compartida \\dominio.local\SYSVOL\dominio.local\scripts y localizar el script de inicio (ej. logon.bat o logon.ps1). Paso 3: Abrir el script en un editor de texto y verificar que las rutas UNC de los servidores compartidos sigan vigentes. Paso 4: Probar la ejecución manual del script en una estación de trabajo cliente para observar si arroja errores de sintaxis o permisos. Paso 5: En la directiva de grupo (GPO), verificar que la directiva Ejecutar scripts de inicio de sesión de forma sincrónica esté habilitada.', 'Evitar colocar contraseñas en texto plano dentro de scripts por lotes almacenados en la carpeta pública SYSVOL.', 4) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-204', 'Detección y eliminación de volcados de memoria minidump huérfanos que saturan el disco C:', 'Paso 1: Si el disco del sistema C: muestra espacio libre crítico menor al 5% y no se identifican archivos de usuario pesados. Paso 2: Abrir cmd como administrador y revisar el tamaño de las carpetas de diagnóstico: C:\Windows\Minidump y C:\Windows\MEMORY.DMP. Paso 3: Si se produjeron pantallas azules recurrentes, Windows puede haber acumulado gigabytes de volcados de memoria completos. Paso 4: Ejecutar la herramienta cleanmgr /sageset:1 marcando Archivos de volcado de memoria de errores del sistema y ejecutar cleanmgr /sagerun:1. Paso 5: Configurar en Propiedades del sistema > Inicio y recuperación el tipo de volcado en Volcado de memoria pequeño (256 KB).', 'Copiar el último archivo minidump a otra unidad si se requiere analizar la causa de una pantalla azul con WinDbg antes de purgar.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-205', 'Procedimiento para pruebas semestrales de conmutación por desastre (Disaster Recovery)', 'Paso 1: Convocar al comité de continuidad del negocio y activar la ventana programada de simulación de desastres. Paso 2: Simular la pérdida del centro de datos principal aislando la red troncal de producción. Paso 3: En el sitio secundario o nube de contingencia, activar la réplica de máquinas virtuales mediante el orquestador de Disaster Recovery (Veeam / Azure Site Recovery). Paso 4: Validar el encendido en orden estricto de dependencias: Controladores de Dominio > Base de Datos > Servidores de Aplicación > Frontend Web. Paso 5: Ejecutar pruebas de humo funcionales con usuarios clave, documentar el RTO y RPO alcanzados y conmutar de retorno a producción.', 'Las pruebas de recuperación ante desastres deben realizarse en una red aislada (Sandbox) para evitar conflictos con los servicios vivos de producción.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-206', 'Para errores de ejecucion en navegadores con aplicaciones web empresariales que requieren Java antiguo', 'Para errores de ejecucion en navegadores con aplicaciones web empresariales que requieren Java antiguo, instalar la version JRE homologada, anadir el sitio a la lista de excepciones de Java y fijar nivel de seguridad en alto.', 'Aislar las versiones heredadas de Java en navegadores dedicados o modo IE para mitigar riesgos de seguridad.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-207', 'Si el aplicativo de gestion documental corporativo no abre documentos PDF en el navegador', 'Si el aplicativo de gestion documental corporativo no abre documentos PDF en el navegador, deshabilitar el visor PDF integrado de Chrome o Edge y asociar Adobe Acrobat Reader como manejador predeterminado.', 'Verificar que la extensión oficial de Adobe Acrobat esté debidamente homologada y actualizada.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-208', 'Ante problemas de compatibilidad en software legado que requiere modo de compatibilidad con Windows 7', 'Ante problemas de compatibilidad en software legado que requiere modo de compatibilidad con Windows 7, aplicar solucionador de problemas de compatibilidad de programas y configurar ejecucion como administrador.', 'Restringir privilegios de administrador local permanente y utilizar elevación controlada LAPS.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-209', 'Cuando una aplicacion cliente servidor reporta perdida de conexion tras periodos de inactividad', 'Cuando una aplicacion cliente servidor reporta perdida de conexion tras periodos de inactividad, configurar politicas de KeepAlive en el registro de Windows para mantener abiertos los sockets TCP en sesiones remotas.', 'Ajustar los tiempos de KeepAlive de acuerdo con las tablas de timeout de estado del firewall perimetral.', 3) ON CONFLICT (runbook_codigo) DO NOTHING;
INSERT INTO servicedesk.articulos_sop_runbooks (runbook_codigo, titulo, contenido, precauciones_criticas, categoria_id) VALUES ('SOP-KB-210', 'Para recuperar archivos cifrados o alterados accidentalmente en carpetas compartidas de red', 'Para recuperar archivos cifrados o alterados accidentalmente en carpetas compartidas de red, restaurar el directorio afectado a partir de la copia de seguridad incremental nocturna mas reciente y auditar el origen del incidente.', 'Aislar de inmediato las máquinas que muestren comportamiento anómalo de cifrado masivo antes de iniciar la restauración.', 2) ON CONFLICT (runbook_codigo) DO NOTHING;
