SET search_path TO servicedesk, public;

UPDATE servicedesk.articulos_sop_runbooks SET search_vector = to_tsvector('spanish', coalesce(titulo, '') || ' ' || coalesce(contenido, '') || ' ' || coalesce(precauciones_criticas, '')) WHERE search_vector IS NULL;

-- Normalización relacional de disciplinas y tipos en taxonomia_activadores
